INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(6, 'koKR', 'Nagroda za Garricka Cichostopego', 'Garrick Cichostopy – rzezimieszek, który od tygodni nęka naszych rolników i kupców – był widziany w szopie przy winnicach, na wschód od opactwa, za mostem. Przynieś mi głowę tego łotra i zgarnij nagrodę!$B$BAle uważaj, $N. Garrick zebrał wokół siebie bandę zbirów. Niełatwo będzie się do niego dostać.', 'Zabij Garricka Cichostopego i przynieś jego głowę zastępcy Willemowi w Opactwie Północnych Włości.', '', 'Wróć do zastępcy Willema w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(7, 'koKR', 'Porządki w obozie koboldów', 'Twoje pierwsze zadanie polega na oczyszczeniu terenu, $N. Klan koboldów zagnieździł się w lasach na północy. Udaj się tam i walcz z koboldzimi szkodnikami, które napotkasz. Przetrzeb ich szeregi, abyśmy pewnego dnia mogli wypędzić ich z Północnych Włości.', 'Zabij 8 koboldzich szkodników, a następnie wróć do marszałka McBride\'a.', '', 'Wróć do marszałka McBride\'a w Opactwie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(11, 'koKR', 'Nagroda za gnole z Wodnołapych', 'Gnole – brutalne stwory, które nie mają czego szukać na tych ziemiach – widziano wzdłuż granic Kniei Elwynn. Duża sfora, znacznie większa, niż jesteśmy w stanie sami pokonać, zagnieździła się w lesie na południe od tamtej wieży strażniczej. Inna grupa opanowała okolice Jeziora Kamiennego Kopca na wschodzie.$B$BArmia Wichrogrodu wyróżni każdego, kto pomoże je wybić. Przynieś mi ich malowane opaski jako dowód twojego czynu.', 'Przynieś 8 malowanych opasek gnoli zastępcy Rainerowi w koszarach.', '', 'Wróć do zastępcy Rainera na Skraju Lasu w Kniei Elwynn.', '', '', '', '', 0),
(15, 'koKR', 'Zbadaj Echową Grań', '$N, moi zwiadowcy donoszą, że plaga koboldów jest większa, niż sądziliśmy. Grupa koboldzich robotników rozbiła obóz w pobliżu Kopalni Echowej Grani na północy.$B$BIdź do kopalni i pozbądź się ich. Wiemy, że jest ich co najmniej ośmiu. Zabij ich, sprawdź, czy nie ma ich więcej, a potem złóż mi raport.', 'Zabij 8 koboldzich robotników, a następnie złóż raport marszałkowi McBride\'owi.', '', 'Wróć do marszałka McBride\'a w Opactwie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(16, 'koKR', 'Daj Gerardowi się napić', '', '', '', 'Wróć do Gerarda Tillera w Kniei Zmierzchu.', '', '', '', '', 0),
(18, 'koKR', 'Bractwo złodziei', 'Od niedawna po Północnych Włościach kręci się nowa banda złodziei. Nazywają siebie Bractwem Nieskornych i widziano ich za rzeką, na wschodzie.$B$BNie wiem, co knują, ale na pewno nic dobrego! Przynieś mi chusty, które noszą, a nagrodzę cię bronią.', 'Przynieś 8 czerwonych jutowych chust zastępcy Willemowi przed Opactwem Północnych Włości.', '', 'Wróć do zastępcy Willema w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(21, 'koKR', 'Potyczka na Echowej Grani', 'Twoje wcześniejsze zwiady dowodzą, że Kopalnię Echowej Grani trzeba oczyścić. Wróć do kopalni i pomóż wykurzyć z niej koboldy.$B$BNie trać czasu, $N. Im dłużej koboldy będą bezkarnie siedzieć w kopalni, tym mocniej zakorzenią się w Północnych Włościach.', 'Zabij 8 koboldzich wyrobników, a następnie wróć do marszałka McBride\'a w Opactwie Północnych Włości.', '', 'Wróć do marszałka McBride\'a w Opactwie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(33, 'koKR', 'Wilki u granic', 'Cokolwiek dręczy te wilki, nie ustępuje. Z każdym dniem chorych wilków przybywa. Z bólem proszę kogokolwiek o zabijanie zwierząt, ale musimy zniszczyć chore młode wilki, zanim ta niewielka zaraza zamieni się w epidemię.$B$BZabij chore młode wilki w dolinie i przynieś mi ich chore wilcze skóry jako dowód twojego czynu.$B', 'Przynieś 8 chorych wilczych skór Eaganowi Skórołupowi przed Opactwem Północnych Włości.', '', 'Wróć do Eagana Skórołupa w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(35, 'koKR', 'Kolejne niepokoje', 'Jeśli obawiasz się, że plotki o murlokach są prawdziwe, zrób tak: udaj się na wschodni most w Elwynn i porozmawiaj ze strażnikiem Thomasem. Od tygodnia stacjonuje przy moście i będzie wiedział, jak wygląda sytuacja w okolicy.$B$BPrzynieś mi jego raport.', 'Marszałek Dughan chce, żebyś $gporozmawiał:porozmawiała; ze strażnikiem Thomasem.', '', '', '', '', '', '', 0),
(37, 'koKR', 'Odnajdź zaginionych strażników', 'Kilka dni temu wysłaliśmy dwóch strażników, Rolfa i Malakaia, żeby zbadali brzeg rzeki, i jeszcze nie wrócili. Żeby dokończyć raport, muszę wiedzieć, co się z nimi stało.$B$BIdź w górę rzeki na północ i odnajdź strażników... albo to, co z nich zostało.', 'Strażnik Thomas chce, żebyś $gposzedł:poszła; w górę rzeki na północ i $godszukał:odszukała; dwóch zaginionych strażników, Rolfa i Malakaia.', '', '', '', '', '', '', 0),
(39, 'koKR', 'Dostarcz raport Thomasa', 'Powiedz marszałkowi Dughanowi o śmierci Malakaia i Rolfa i zamelduj mu, że obecne siły nie są w stanie powstrzymać murloków we wschodnim Elwynn.$B$BWiem, że nie mamy wielu wolnych żołnierzy, ale może Dughan kogoś znajdzie.', 'Zamelduj się u marszałka Dughana w Złotych Włościach.', '', '', '', '', '', '', 0),
(40, 'koKR', 'Rybie zagrożenie', '$N, w Kniei Elwynn pojawiło się nowe zagrożenie! Murloki płyną w górę strumieni wschodniego Elwynn, płoszą ryby i napadają na spokojnych ludzi!$B$BOstrzegłem marszałka Dughana, ale on bardziej martwi się gnolami i bandytami. Nie jest przekonany, że murloki stanowią zagrożenie.$B$BProszę, $N, porozmawiaj z Dughanem i przekonaj go, żeby wysłał więcej żołnierzy na wschód!', 'Remy „Dwa Razy” chce, żebyś $gporozmawiał:porozmawiała; z marszałkiem Dughanem w Złotych Włościach.', '', '', '', '', '', '', 0),
(45, 'koKR', 'Odkryj los Rolfa', 'Po dokładniejszym przeszukaniu okolicy znajdujesz ślady płetwiastych stóp prowadzące na wschód wzdłuż brzegu Jeziora Kamiennego Kopca. W oddali na wschodzie ledwie widać wioskę murloków.$B$BByć może tam dopełnił się los Rolfa...', 'Przeszukaj wioskę murloków w poszukiwaniu Rolfa lub śladów jego śmierci.', '', '', '', '', '', '', 0),
(46, 'koKR', 'Nagroda za murloki', 'Armia Wichrogrodu wyznaczyła nagrodę za czyhające murloki i murloki zbieracze w Elwynn. Wyrżnij je i przynieś mi ich rozdarte płetwy, a Armia Wichrogrodu sowicie cię wynagrodzi.$B$BMurloki zbudowały wioskę nad Jeziorem Kamiennego Kopca na północ stąd i drugą na południu, tam gdzie rozwidla się strumień.', 'Przynieś 8 rozdartych płetw murloków strażnikowi Thomasowi przy wschodnim moście w Elwynn.', '', 'Wróć do strażnika Thomasa w Kniei Elwynn.', '', '', '', '', 0),
(47, 'koKR', 'Wymiana złotego pyłu', 'Koboldy w tych stronach czasem noszą przy sobie złoty pył. Bardzo by mi się przydał – przynieś mi go trochę, a dam ci najlepszą cenę w mieście... najlepszą cenę w mieście!$B$BKoboldy znajdziesz w Kopalni Dalekiej Głębi na południu i w okolicy Kopalni Jaspisowej Żyły na północnym wschodzie.', 'Przynieś 10 porcji złotego pyłu Remy\'emu „Dwa Razy” w Złotych Włościach. Złoty pył można zdobyć od koboldów w Kniei Elwynn.', '', 'Wróć do Remy\'ego „Dwa Razy” w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(52, 'koKR', 'Chroń pogranicze', 'Witaj, $N. Im dalej od Złotych Włości, tym dzikie zwierzęta stają się coraz agresywniejsze, a obóz drwali we Wschodniej Dolinie jest niemal bez przerwy atakowany przez wilki i niedźwiedzie!$B$BPrzydałaby się nam tu twoja pomoc.', 'Zabij 8 drapieżców i 5 młodych leśnych niedźwiedzi, a następnie wróć do strażnika Thomasa przy wschodnim moście w Elwynn.', '', 'Wróć do strażnika Thomasa w Kniei Elwynn.', '', '', '', '', 0),
(54, 'koKR', 'Zgłoś się w Złotych Włościach', '$N, jako $c $gwykazałeś:wykazałaś; się troską o bezpieczeństwo Północnych Włości. Teraz powierzam ci ochronę okolicznej Kniei Elwynn.$B$BJeśli przyjmujesz to zadanie, mam przygotowane dokumenty, które trzeba dostarczyć marszałkowi Dughanowi w Złotych Włościach. Złote Włości leżą przy drodze na południe, za bramami granicznymi.', 'Zanieś dokumenty marszałka McBride\'a marszałkowi Dughanowi w Złotych Włościach.', '', '', '', '', '', '', 0),
(59, 'koKR', 'Zbroja z płótna i skóry', 'W nagrodę za spryt i męstwo mam tu znacznik, który można wymienić na jedną część zbroi. Zanieś go Sarze Timberlain do obozu drwali we Wschodniej Dolinie. Daj jej znacznik, a ona przygotuje dla ciebie zbroję. A kiedy ją dostaniesz, $N, użyj jej w obronie Elwynn.$B$BObóz drwali we Wschodniej Dolinie leży za posterunkiem strażnika Thomasa, na wschodzie.', 'Oddaj Sarze Timberlain znacznik zbroi Wichrogrodu.', '', '', '', '', '', '', 0),
(60, 'koKR', 'Koboldzie świece', 'Witaj, $gszanowny panie:szanowna pani;! Masz chwilę?$B$BRazem z bratem prowadzimy aptekę w Wichrogrodzie, a ja przyjechałem tu zebrać duże świece dla ich wosku. Pomożesz mi?$B$BDuże świece można zdobyć od koboldów, a słyszałem plotki, że koboldy zagnieździły się w kopalniach Elwynn... w Kopalni Dalekiej Głębi na południu i w Kopalni Jaspisowej Żyły na wschodzie. Radzę szukać świec w jednym z tych miejsc.', 'Przynieś 8 dużych świec Williamowi Pestle\'owi w Złotych Włościach.', '', 'Wróć do Williama Pestle\'a w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(61, 'koKR', 'Dostawa do Wichrogrodu', 'Mój brat Morgan czeka w Wichrogrodzie na dostawę świec. Nie mam czasu, żeby samemu tam jechać, ale jeśli zechcesz zanieść mu przesyłkę, dobrze ci zapłaci.$B$BŚwiece już zapakowałem, a Morgana znajdziesz w naszym sklepie, Aptece Pestle\'a, w Dzielnicy Handlowej Wichrogrodu.', 'Zanieś przesyłkę Williama Morganowi Pestle\'owi w Dzielnicy Handlowej Wichrogrodu.', '', '', '', '', '', '', 0),
(62, 'koKR', 'Kopalnia Dalekiej Głębi', 'Nie tylko kopalnia w Północnych Włościach ma kłopoty! Dostaję raporty, że Kopalnia Dalekiej Głębi w Elwynn również stała się schronieniem dla koboldów.$B$BZbadaj kopalnię, potwierdź te doniesienia, a potem wróć do mnie. Kopalnia leży niemal dokładnie na południe od Złotych Włości, między zagrodami Stonefieldów i Maclure\'ów.', 'Zbadaj Kopalnię Dalekiej Głębi, a następnie wróć do marszałka Dughana w Złotych Włościach.', 'Przeprowadź zwiad w Kopalni Dalekiej Głębi', 'Wróć do marszałka Dughana w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(69, 'koKR', 'Legenda o Stalvanie', 'O rety! Musiałem to przeoczyć za pierwszym razem. W rejestrze, tuż pod pierwszym adresem Stalvana, jest wpisany jeszcze jeden, tylko częściowo wydrapany. Wygląda na to, że udawał się do karczmy „Lwia Duma” w Złotych Włościach. Warto tam zajrzeć, $N.', 'Udaj się do karczmy „Lwia Duma” i sprawdź, czy ktoś tam słyszał o Stalvanie.', '', '', '', '', '', '', 0),
(70, 'koKR', 'Legenda o Stalvanie', 'Imię Stalvan coś mi mówi. Już pamiętam.$b$bWiele lat temu, w burzową noc, przybył tu posłaniec, szukając schronienia na noc. Tuż przed północą ten człowiek zbiegł po schodach z krzykiem, z twarzą bladą ze strachu. Wciąż w nocnej koszuli zniknął w ulewie.$b$bW pośpiechu zostawił swoje listy w skrzyni na górze. Nigdy po nie nie wrócił. Został jeden od tego Stalvana, zaadresowany do Dzielnicy Kanałów w Wichrogrodzie. Weź go sobie.', 'Wyjmij ze skrzyni niedostarczony list Stalvana i dostarcz go do Dzielnicy Kanałów w Wichrogrodzie.', '', 'Porozmawiaj z dozorcą Folsomem w Wichrogrodzie.', '', '', '', '', 0),
(71, 'koKR', 'Raport dla Thomasa', 'Teraz, gdy masz oba medaliony, zanieś je strażnikowi Thomasowi przy moście, żeby poznał los swoich zamordowanych strażników.', 'Dostarcz medaliony Rolfa i Malakaia strażnikowi Thomasowi przy wschodnim moście w Elwynn.', '', '', '', '', '', '', 0),
(74, 'koKR', 'Legenda o Stalvanie', 'W skrzyni znajdujesz różne przedmioty: zatęchłe pamiątki rodzinne, portret rodzinny, kilka myśliwskich trofeów i parę starych ksiąg. Przy samym dnie, pod ceramicznym wazonem, odkrywasz podartą stronę dziennika.', 'Podarta strona dziennika, którą $gznalazłeś:znalazłaś;, jest twoją następną wskazówką.', '', '', '', '', '', '', 0),
(75, 'koKR', 'Legenda o Stalvanie', 'Kiedy się tu wprowadziłem, w skrzyni na górze leżał plik pergaminów. Przejrzałem je raz, zaraz po przybyciu, ale dałem sobie spokój, kiedy mgła zasnuła mi ślepia.$b$bZrób przysługę staremu, niemal ślepemu człowiekowi i sprawdź skrzynię na górze – może znajdziesz coś, co pomoże ci dowiedzieć się więcej o tym całym Stalvanie. Jestem prawie pewien, że jest tam wyblakła strona dziennika, która może cię zainteresować. Przynieś mi ją, a pomogę, jak tylko zdołam.', 'Marszałek Haggard chce, żebyś $gsprawdził:sprawdziła;, czy w skrzyni na górze jest wyblakła strona dziennika.', '', 'Wróć do marszałka Haggarda w obozie drwali we Wschodniej Dolinie w Kniei Elwynn.', '', '', '', '', 0),
(76, 'koKR', 'Kopalnia Jaspisowej Żyły', 'Dzięki tobie wiemy, że w Kopalni Dalekiej Głębi roi się od koboldów. Teraz potrzebujemy zwiadowcy, który zbada położoną dalej Kopalnię Jaspisowej Żyły.$B$BZbadaj Kopalnię Jaspisowej Żyły i potwierdź, czy są tam koboldy. Żeby do niej dotrzeć, idź drogą na wschód aż do Wieży Azory. Od wieży skręć na północ, a znajdziesz kopalnię u podnóża wzgórz.', 'Zbadaj Kopalnię Jaspisowej Żyły, a następnie złóż raport marszałkowi Dughanowi w Złotych Włościach.', 'Przeprowadź zwiad w Kopalni Jaspisowej Żyły', 'Wróć do marszałka Dughana w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(78, 'koKR', 'Legenda o Stalvanie', 'Znam kogoś, kto może ci pomóc. Kiedy dowodziłem strażą Wichrogrodu, chadzaliśmy na drinka do tawerny „Szkarłatny Kruk” w Mrocznych Włościach. Tamtejszy szynkarz, Smitts, był prawdziwym znawcą miejscowych opowieści. Pokaż mu tę stronę i zobacz, co o niej powie.', 'Zanieś wyblakłą stronę dziennika szynkarzowi Smittsowi w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', '', '', 0),
(83, 'koKR', 'Wyroby z czerwonego lnu', 'Banda Nieskornych w Północnych Włościach nosi maski z juty, ale Nieskorni w Elwynn noszą lniane, z których mogę uszyć porządne lniane wyroby.$B$BPrzynieś mi czerwone lniane chusty, a uszyję z nich coś dla ciebie.$B$BCzłonkowie bandy Nieskornych mają obozy porozrzucane po całym Elwynn.', 'Przynieś 6 czerwonych lnianych chust Sarze Timberlain do obozu drwali we Wschodniej Dolinie.', '', 'Wróć do Sary Timberlain w obozie drwali we Wschodniej Dolinie w Kniei Elwynn.', '', '', '', '', 0),
(84, 'koKR', 'Z powrotem do Billy\'ego', 'Proszę bardzo. A kiedy dasz ten placek temu Billy\'emu, powiedz mu, że mam nadzieję, że się nim udławi!', 'Zanieś placek z boczkiem Billy\'emu Maclure\'owi w winnicach Maclure\'ów.', '', '', '', '', '', '', 0),
(85, 'koKR', 'Zgubiony naszyjnik', 'Zgubiłam naszyjnik i myślę, że zabrał go ten łobuz Billy Maclure! Zwykle kręci się jak szczur po winnicach Maclure\'ów na wschód stąd.$B$BOdzyskaj dla mnie naszyjnik, a ogrzejesz serce starej wdowy.', 'Porozmawiaj z Billym Maclure\'em.', '', '', '', '', '', '', 0),
(86, 'koKR', 'Placek dla Billy\'ego', 'Może gdybym dostał placek, powiedziałbym ci, kto ma ten naszyjnik. A wiesz, myślę, że ta stara Bernice z tamtej farmy piecze świetne placki z boczkiem...$B$BMoże gdybyś $gdał:dała; jej trochę dziczyzny z dzików, które kręcą się koło naszych farm, i $gpowiedział:powiedziała;, na co to, upiekłaby dla ciebie placek.', 'Przynieś 4 kawały dziczyzny „Cioci” Bernice Stonefield na farmę Stonefieldów.', '', 'Wróć do „Cioci” Bernice Stonefield na farmie Stonefieldów w Kniei Elwynn.', '', '', '', '', 0),
(87, 'koKR', 'Złotozęby', 'Bawiłem się koło Kopalni Dalekiej Głębi i chyba upuściłem, eee... to znaczy widziałem naszyjnik tej starszej pani. Nie pytaj, skąd się tam wziął... to nie ja!$B$BW każdym razie widziałem, jak wielki kobold ze złotym zębem podnosi naszyjnik i ucieka z nim do kopalni. Znajdź tego kobolda, a znajdziesz naszyjnik, przysięgam!', 'Zanieś naszyjnik Bernice „Cioci” Bernice Stonefield na farmę Stonefieldów.', '', 'Wróć do „Cioci” Bernice Stonefield na farmie Stonefieldów w Kniei Elwynn.', '', '', '', '', 0),
(88, 'koKR', 'Księżniczka musi zginąć!', 'Brackwellowie mają nagradzaną świnię, Księżniczkę. Ta locha jest OGROMNA, a utyła tak, bo zakradała się tutaj i zjadała moje warzywa!$B$BWięc zanim znowu przyjdzie na nasze pola... Księżniczka musi zginąć! Przynieś mi jej obrożę na dowód, a dam ci coś za fatygę!$B$BKsiężniczka zwykle przebywa na dyniowym polu Brackwellów, na wschód stąd, za farmą Maclure\'ów. Dopadnij ją, zanim zgłodnieje i wróci tutaj!', 'Zabij Księżniczkę, zabierz jej obrożę i zanieś ją Mamie Stonefield na farmę Stonefieldów.', '', 'Wróć do Mamy Stonefield na farmie Stonefieldów w Kniei Elwynn.', '', '', '', '', 0),
(94, 'koKR', 'Czujne oko', 'Mój rywal, Morganth, to okrutny mag o wielkiej mocy, który mieszka w Wieży Ilgalara w Górach Rudej Grani. Opracowałem sposób, by go szpiegować – Oko Azory – i teraz mogę obserwować go z daleka.$B$BAle żeby zgłębić jego myśli... potrzebuję dodatkowej pomocy.$B$BJeśli chcesz, zanieś mój Glif Azory do Wieży Ilgalara. Umieść go na posągu lwa w pobliżu wieży.$B$BGdy to zrobisz, moc Azory ukaże mi wizje przyszłych planów Morgantha.', 'Zanieś Glif Azory do posągu lwa w pobliżu Wieży Ilgalara w Górach Rudej Grani.', '', '', '', '', '', '', 0),
(106, 'koKR', 'Młodzi kochankowie', 'Och, jestem przeklęta! Moje serce należy do Tommy\'ego Joe Stonefielda, ale nasze rodziny są zaciekłymi wrogami. Nie mogę się z nim widywać, choć oczy bolą mnie z tęsknoty za jego przystojną twarzą!$B$BProszę, weź ten list i daj go Tommy\'emu Joe. Zwykle przesiaduje nad rzeką na zachód od farmy Stonefieldów, która leży dokładnie na zachód stąd.', 'Daj list miłosny Maybell Tommy\'emu Joe Stonefieldowi.', '', '', '', '', '', '', 0),
(107, 'koKR', 'Liścik do Williama', 'Założę się, że William Pestle ma miksturę, która połączy naszych młodych kochanków!$B$BProszę, zanieś ten liścik Williamowi. Zatrzymał się w karczmie „Lwia Duma” w Złotych Włościach.', 'Zanieś liścik babci Stonefield Williamowi Pestle\'owi.', '', '', '', '', '', '', 0),
(109, 'koKR', 'Zgłoś się do Gryana Mocnopłaszcza', 'Wygląda na to, że $gstoczyłeś:stoczyłaś; w swoim życiu sporo walk. Jeśli jeszcze tego nie $gzrobiłeś:zrobiłaś;, zgłoś się do Gryana Mocnopłaszcza. Stoi na czele Milicji Ludowej, która chroni pola uprawne Zachodniego Skraju. Założę się, że przyda mu się twoja pomoc. Zwykle można go znaleźć w kamiennej wieży na Wzgórzu Strażniczym, tuż przy drodze w środku Zachodniego Skraju.', 'Porozmawiaj z Gryanem Mocnopłaszczem. Zwykle można go znaleźć w kamiennej wieży na Wzgórzu Strażniczym, tuż przy drodze, w środku Zachodniego Skraju.', '', '', '', '', '', '', 0),
(111, 'koKR', 'Porozmawiaj z babcią', 'Proszę, $N, porozmawiaj z moją babcią. Jeśli ktokolwiek potrafi znaleźć sposób, żebym był z Maybell, to właśnie ona.$B$BJest w naszym domu na wschód stąd.', 'Porozmawiaj z babcią Stonefield.', '', '', '', '', '', '', 0),
(112, 'koKR', 'Zbieranie wodorostów', 'Mogę zrobić dla Maybell trunek niewidzialności, żeby wymknęła się z winnic Maclure\'ów i poszła do Tommy\'ego Joe. Ale żeby go przyrządzić, potrzebuję kryształowych wodorostów.$B$BChoć wodorosty zwykle rosną w oceanie... murloki czasem je zbierają. Sprawdź, czy murloki przy Kryształowym Jeziorze jakieś mają. Kryształowe Jezioro leży tuż na wschód od Złotych Włości.', 'Przynieś 4 liście kryształowego wodorostu Williamowi Pestle\'owi w Złotych Włościach.', '', 'Wróć do Williama Pestle\'a w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(114, 'koKR', 'Ucieczka', 'Zanieś ten trunek niewidzialności młodej Maybell. Powinien działać wystarczająco długo, żeby mogła odwiedzić Tommy\'ego Joe.', 'Zanieś trunek niewidzialności Maybell Maclure.', '', '', '', '', '', '', 0),
(118, 'koKR', 'Cena podków', 'Zużywam tyle żelaza na wyposażenie straży Wichrogrodu, że nie starcza mi na podkowy dla koni ze stajni!$B$BZanieś ten liścik kowalowi Argusowi w Złotych Włościach. Wyjaśniam w nim swój kłopot i proszę o dostawę podków.', 'Zanieś liścik Vernera kowalowi Argusowi w Złotych Włościach w Kniei Elwynn.', '', '', '', '', '', '', 0),
(119, 'koKR', 'Powrót do Vernera', 'Dobra, dam mu te jego 50 podków...$B$BOto one, zapakowane i gotowe do drogi! Powiedz Vernerowi, że miło robić z nim interesy, i dopilnuj, żeby przeczytał liścik przyczepiony do skrzynki!', 'Wróć do Vernera Osgooda w Jeziernych Włościach w Górach Rudej Grani. Oddaj mu skrzynkę podków.', '', '', '', '', '', '', 0),
(123, 'koKR', 'Kolekcjoner', 'Ten liścik to harmonogram z listą dni i godzin, w których pewna osoba – opisana jedynie jako „Kolekcjoner” – ma odbierać dostawy złota z kopalń w Kniei Elwynn.$B$BZ harmonogramu wynika, że Kolekcjoner przebywa w pobliżu dyniowego pola Brackwellów we wschodnim Elwynn.$B$BTo brzmi poważnie. $GPowinieneś:Powinnaś; zgłosić to marszałkowi Dughanowi w Złotych Włościach.', 'Udaj się do marszałka Dughana w Złotych Włościach i daj mu harmonogram Kolekcjonera.', '', '', '', '', '', '', 0),
(147, 'koKR', 'Obława', 'Jeśli „Kolekcjoner” zabiera złoto z naszych kopalń, to okrada królestwo! Postaw go przed obliczem sprawiedliwości i przynieś mi pierścień, o którym wspomina harmonogram, który mi $gdałeś:dałaś;. Może nam powiedzieć, dla kogo Kolekcjoner pracuje...$B$BZ harmonogramu wynika, że Kolekcjoner ukrywa się na dyniowym polu Brackwellów. Tam go szukaj.', 'Znajdź i zabij „Kolekcjonera”, a następnie wróć do marszałka Dughana z pierścieniem Kolekcjonera.', '', 'Wróć do marszałka Dughana w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(176, 'koKR', 'Poszukiwany: „Wyżer”', 'Poszukiwany: Wyżer$B$BOgromny gnol, Wyżer, grasuje w lasach południowo-zachodniego Elwynn. Udaremnił wszystkie próby schwytania go.$B$BArmia Wichrogrodu wyznaczyła za gnola hojną nagrodę. Aby ją otrzymać, łowcy nagród powinni dostarczyć dowód śmierci Wyżera marszałkowi Dughanowi w Złotych Włościach.', 'Zabij gnola Wyżera i zanieś jego ogromny pazur marszałkowi Dughanowi.', '', 'Wróć do marszałka Dughana w Złotych Włościach w Kniei Elwynn.', '', '', '', '', 0),
(178, 'koKR', 'Zguba Theocritusa', '<Słyszysz bezcielesny głos...>$B$BNie lękaj się. Jestem Theocritus, arcymag Wieży Azory w Kniei Elwynn. Wisior, który trzymasz, służy do porozumiewania się gnoli z klanu Cienioskórych z ich panem, Morganthem.$B$BPo miesiącach badań doszedłem do wniosku, że ja również mogę porozumiewać się przez te wisiory. Jeśli słyszysz tę wiadomość, moje zaklęcie się powiodło.$B$BPrzynieś mi ten wisior, a wynagrodzę cię za przysługę.', 'Zanieś wyblakły wisior Cienioskórych magowi Theocritusowi do Wieży Azory w Kniei Elwynn.', '', '', '', '', '', '', 0),
(239, 'koKR', 'Garnizon Zachodniego Potoku potrzebuje pomocy!', 'Garnizon na naszej zachodniej granicy donosi o coraz większej aktywności gnoli i złodziei. Proszą o przysłanie kolejnych żołnierzy Wichrogrodu... ale po prostu nie mamy wolnych ludzi!$B$BJeśli możesz pomóc, bardzo się przydasz. Idź do Garnizonu Zachodniego Potoku, porozmawiaj z zastępcą Rainerem i dowiedz się, czego potrzebuje.$B$BGarnizon leży przy drodze na zachód. Gdy przejdziesz przez most nad strumykiem, będzie po prawej.', 'Udaj się do Garnizonu Zachodniego Potoku i porozmawiaj z zastępcą Rainerem.', '', '', '', '', '', '', 0),
(249, 'koKR', 'Morganth', 'Po długich obserwacjach odkryłem plany Morgantha.$B$BSzuka Kosy Eluny... i być może już ją znalazł! Jeśli tak, Góry Rudej Grani, a także królestwo Wichrogrodu, wkrótce poczują jego mroczną potęgę.$B$BNie jestem gotów stanąć przeciw Morganthowi, ale obawiam się, że trzeba się nim zająć już teraz. Musisz więc wejść do Wieży Ilgalara i stawić czoła Morganthowi.$B$BPokonaj go i przynieś mi jego Wisior cienia. Zrób to, a królestwo będzie ci wiele zawdzięczać.', 'Pokonaj Morgantha.$B$BZanieś jego Wisior cienia Theocritusowi do Wieży Azory w Kniei Elwynn.', '', 'Wróć do Theocritusa w Wieży Azory w Kniei Elwynn.', '', '', '', '', 0),
(344, 'koKR', 'Brat Paxton', '„Naprężenia żelaza”? Tak, znam tę księgę. Całkiem dobra, napisał ją kilkadziesiąt lat temu krasnoludzki górnik Margulf Blaggon. Większość życia spędził głęboko w górach Khaz Modan, wydobywając rudę. Mądry gość!$B$BAle o czym to ja...? A tak, „Naprężenia żelaza”! Obawiam się, że księgę przeniesiono do Opactwa Północnych Włości. Opiekun biblioteki opactwa, brat Paxton, chciał zrobić jej odpis na własne półki.$B$BAle to było przed wieloma miesiącami. Ciekawe, czemu zajmuje mu to tyle czasu...', 'Porozmawiaj z bratem Paxtonem w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(345, 'koKR', 'Zapasy atramentu', 'Od dawna zamierzam dokończyć swój odpis „Naprężeń żelaza”, ale...$B$BWidzisz, do przepisywanych ksiąg robię własny atrament. To mój własny przepis: nie rozmazuje się, nie spływa i schnie bardzo szybko. Niestety, schnie za szybko! Ostatnia porcja wyschła, zanim skończyłem przepisywanie, a nie miałem okazji zrobić nowej!$B$BŻeby zrobić więcej, potrzebuję rudy żelaza z Rethbanu z Gór Rudej Grani. Zwykle dostarcza mi ją brygadzista Oslow z Jeziernych Włości.', 'Porozmawiaj z brygadzistą Oslowem w Jeziernych Włościach i poproś go o rudę żelaza z Rethbanu.', '', '', '', '', '', '', 0),
(346, 'koKR', 'Powrót do Kristoffa', 'Skoro skończyłem przepisywać księgę, oto oryginał „Naprężeń żelaza”. Dziękuję za cierpliwość, a jeśli spotkasz Miltona, przekaż mu, proszę, że przepraszam za tak długą zwłokę.', 'Wróć do brata Kristoffa na Placu Katedralnym. Oddaj mu księgę „Naprężenia żelaza”.', '', '', '', '', '', '', 0),
(347, 'koKR', 'Ruda z Rethbanu', 'Ruda z Rethbanu nosi imię człowieka, który pierwszy ją znalazł, Barta Rethbana. Po wytopieniu nie jest tak mocna jak żelazo, ale ma ciemną, matową barwę, której niektórzy skrybowie używają do barwników. Można ją znaleźć w Jaskiniach Rethbanu, na północ stąd.$B$BZwykle mamy jej trochę w zapasie, ale jesteśmy zbyt zajęci przygotowaniami do napaści orków, żeby ją wydobywać. Poza tym... w Jaskiniach Rethbanu zamieszkały gnole z Rudej Grani, a ich harownicy sami wydobywają rudę.$B$BWięc jeśli jej potrzebujesz, musisz ją zdobyć $gsam:sama;.', 'Zbierz 5 porcji rudy z Rethbanu i zanieś ją bratu Paxtonowi do biblioteki w Północnych Włościach.', '', 'Wróć do brata Paxtona w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(783, 'koKR', 'Zagrożenie od wewnątrz', 'Mam nadzieję, że mocno $gzapiąłeś:zapięłaś; pas, bo w Północnych Włościach jest robota nawet dla kogoś tak $gmłodego:młodej; jak ty.$B$BI nie mam na myśli pracy w polu.$B$BStraż Wichrogrodu ledwo daje radę utrzymać tu spokój – tak wielu z nas walczy w dalekich krainach, a tak wiele zagrożeń czai się tuż obok. Dlatego prosimy o pomoc każdego, kto chce bronić swojego domu. I swojego Przymierza.$B$BJeśli $gprzybyłeś:przybyłaś;, by odpowiedzieć na wezwanie, porozmawiaj z moim przełożonym, marszałkiem McBride\'em. Jest w opactwie za mną.', 'Porozmawiaj z marszałkiem McBride\'em.', '', '', '', '', '', '', 0),
(1097, 'koKR', 'Zadanie Elmore\'a', 'W Wichrogrodzie jest krasnoludzki płatnerz, Grimand Elmore, który dał znać, że potrzebuje pomocy przy dostawie. Zdaje się, że chce wysłać paczkę do swojej ojczyzny na północy.$B$BMasz mocne nogi! Więc jeśli nie boisz się trochę pobiegać, porozmawiaj z Grimandem. $GPrzydałbyś:Przydałabyś; się nam tutaj, ale musimy też dbać o dobre stosunki z krasnoludami.$B$BGrimanda Elmore\'a znajdziesz w sklepie z bronią w Dzielnicy Krasnoludów w Wichrogrodzie, w północno-wschodniej części miasta.', 'Porozmawiaj z Grimandem Elmore\'em w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1638, 'koKR', 'Szkolenie wojownika', '$GPokazałeś:Pokazałaś;, że $gjesteś kompetentnym wojownikiem:jesteś kompetentną wojowniczką;, $N. Ale wciąż $gjesteś młody:jesteś młoda; i wiele musisz się nauczyć.$B$BPorozmawiaj z Harrym Burlguardem – zwykle przesiaduje w tawernie „Świnia i Gwizdek” na Starym Mieście w Wichrogrodzie. Harry to stary weteran i dobry nauczyciel. Pokaże ci kilka ruchów, dzięki którym dłużej pooddychasz.', 'Porozmawiaj z Harrym Burlguardem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1666, 'koKR', 'Marszałek Haggard', '$GNauczyłeś:Nauczyłaś; się kilku ruchów, ale wciąż przydałaby ci się porządna broń. Założę się, że marszałek Haggard mógłby ci pomóc.$B$BMarszałek Haggard mieszka we dworze w Kniei Elwynn, przy obozie drwali we Wschodniej Dolinie. Jest już na emeryturze, ale przez lata służby zebrał mnóstwo sprzętu.$B$BPowiedz mu, że to ja cię przysyłam, a przy odrobinie szczęścia znajdzie dla ciebie jakąś zbędną broń.', 'Porozmawiaj z marszałkiem Haggardem.', '', '', '', '', '', '', 0),
(1667, 'koKR', 'Martwozęby Jack', 'Burlguard cię przysłał, tak? Owszem, mam tu trochę zbędnej broni, ale najpierw mam dla ciebie zadanie...$B$BJakiś czas temu oszukał mnie Martwozęby Jack, łotr z Bractwa Nieskornych. Było ciemno, miał na sobie tabard Wichrogrodu, a ja wziąłem go za marszałka Dughana. Powiedział, że potrzebuje mojej starej odznaki marszałka Wichrogrodu, a ja mu ją dałem... a on się roześmiał i uciekł, zanim zdążyłem go złapać!$B$BOdzyskaj moją odznakę! Martwozęby Jack pewnie schował ją w swoim obozie na południu.', 'Odzyskaj odznakę Haggarda z obozu Martwozębego Jacka i wróć do marszałka Haggarda.', '', 'Wróć do marszałka Haggarda nad Jeziorem Kamiennego Kopca w Kniei Elwynn.', '', '', '', '', 0),
(1685, 'koKR', 'Wezwanie od Gakina', 'Czy nie zawsze tak jest? Szukałem cię cały dzień i nie mogłem znaleźć, a teraz, kiedy się tego nie spodziewam, $gsam:sama; do mnie podchodzisz.$b$bStraciłem już dość czasu na szukanie cię, więc nie będę cię dłużej zatrzymywać. Mistrz Gakin wzywa cię na dalsze szkolenie. Moim zdaniem $gpowinieneś:powinnaś; odszukać go jak najszybciej.$b$bZnajdziesz go w piwnicy tawerny „Zarżnięte Jagnię”. A przy okazji, lepiej nie rozgłaszaj tego miejsca. Nie chcemy, żeby wieść się rozniosła.', 'Zamelduj się u Gakina Mrokospętacza w Dzielnicy Magów w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1786, 'koKR', 'Księga Boskości', 'Razem z Henzem dotarliśmy do Czuwania Bohaterów, wyspy pośrodku Jeziora Kamiennego Kopca w północno-wschodnim Elwynn. Słyszeliśmy, że Nieskorni przeniknęli przez nasze granice, i chcieliśmy zdobyć dowód dla doradców króla.$B$BWypatrzyliśmy kilku tych szubrawców przeglądających jakieś dokumenty i zaatakowaliśmy. Niestety, szybko przytłoczyło nas więcej magów.$B$BHenze powstrzymywał ich, a ja uciekłem... głupiec, musiał zgrywać bohatera.$B$BWciąż tam jest, Henze. Pomożesz nam, $N?', 'Weź Symbol Życia i wskrześ Henzego Faulka w Elwynn.', '', '', '', '', '', '', 0),
(1787, 'koKR', 'Księga Boskości', 'O Symbolu porozmawiamy później. Teraz najważniejsze jest zdobycie tych papierów, które przeglądali Nieskorni. Jeśli wpadną w nasze ręce, udowodnimy, że Nieskorni przeniknęli do Elwynn, i być może dowiemy się, jakie mają plany.$B$BNa razie nie nadaję się do walki, $N. Myślisz, że jesteś $gdość silny:dość silna;, by odebrać te papiery Nieskornym tu, na wyspie?$B$BJeśli ci się uda, zanieś je Gazinowi i powiedz mu, że nic mi nie jest.', 'Zdobądź pismo Nieskornych od czarodziejów-łotrów Nieskornych w Elwynn i wróć do Gazina Tenorma w Wichrogrodzie.', '', 'Wróć do Gazina Tenorma w Wichrogrodzie.', '', '', '', '', 0),
(1860, 'koKR', 'Porozmawiaj z Jenneą', 'My, magowie, mamy zadanie do wykonania. Zadanie kluczowe dla bezpieczeństwa Wichrogrodu i Kniei Elwynn.$B$BSzczegóły zna Jennea Cannon. Studiuje w sanktuarium czarodziejów, w Dzielnicy Magów w Wichrogrodzie. Udaj się do niej bez zwłoki.', 'Porozmawiaj z Jenneą Cannon w Wichrogrodzie.', '', '', '', '', '', '', 0),
(1919, 'koKR', 'Zgłoś się do Jennei', 'Twoja wiedza o sztuce rośnie, $N. Czy jesteś już $ggotów:gotowa; rozpocząć prawdziwą naukę? Czy jesteś $ggotów:gotowa; zająć swoje miejsce w tajnej wojnie, którą toczymy?$B$BJeśli tak, porozmawiaj z Jenneą Cannon w sanktuarium czarodziejów w Dzielnicy Magów w Wichrogrodzie. Ma dla ciebie zadanie, które otworzy ci pierwsze okno na niewidzialny świat.', 'Porozmawiaj z Jenneą Cannon w Wichrogrodzie.', '', '', '', '', '', '', 0),
(2158, 'koKR', 'Odpoczynek i relaks', 'Każdy poszukiwacz przygód powinien odpocząć, gdy dopada go zmęczenie – a nie ma lepszego miejsca na odpoczynek i relaks niż karczma „Lwia Duma”!$B$BMój najlepszy przyjaciel, karczmarz Farley, prowadzi „Lwią Dumę”. Jeśli powiesz mu, że to ja cię przysyłam, może da ci specjalną zniżkę na jedzenie i picie.$B$BŻeby trafić do „Lwiej Dumy”, idź stąd drogą na południe – nie da się jej przeoczyć!', 'Porozmawiaj z karczmarzem Farleyem w karczmie „Lwia Duma”.', '', '', '', '', '', '', 0),
(2205, 'koKR', 'Odszukaj WW:7', 'Odznaka? Ach, to nic, płotko – nic, z czym $gdałbyś:dałabyś; sobie radę. Sądząc po twoim wyglądzie, Mathias pewnie weźmie cię raczej za $gchłopaka:dziewczynę; od dostawy sera niż za prawdziwego łotra. Tak czy inaczej, dostałam zlecenie i obiecałam je wykonać.$B$BA skoro o tym mowa, zanieś tę paczkę Mathiasowi, a może da ci jakieś drobne zadanie czy dwa.$B$BDo roboty.$B', 'Dostarcz paczkę Keryn Sylvius mistrzowi Mathiasowi Shaw w koszarach Wichrogrodu.', '', '', '', '', '', '', 0),
(2300, 'koKR', 'WW:7', 'Renzik cię szukał, płotko.$B$BNa twoim miejscu nie kazałabym czekać zastępcy Mathiasa.$B', 'Udaj się do Wichrogrodu i odszukaj Renzika „Kosę”.', '', '', '', '', '', '', 0),
(2998, 'koKR', 'Księga Boskości', 'Witaj, $gbracie:siostro;. Duthorian Rall, jeden z naszych najbardziej wpływowych paladynów, niedawno o tobie mówił. Słyszałem, jak mówił, że nadszedł czas, by poddać cię próbie... i wypowiadał się bardzo pochlebnie o tym, jak dotąd się $gspisałeś:spisałaś;.$B$BNa twoim miejscu, gdy znajdziesz czas, udałbym się do Wichrogrodu i z nim porozmawiał. Na pewno jest w Katedrze Światła – tam spędza większość czasu.', 'Porozmawiaj z Duthorianem Rallem w Wichrogrodzie.', '', '', '', '', '', '', 0),
(3100, 'koKR', 'Zwykły list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią Llane\'a, naszego miejscowego nauczyciela wojowników. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj zwykły list i porozmawiaj z Llane\'em Beshere\'em w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(3101, 'koKR', 'Poświęcony list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią brata Sammuela, naszego miejscowego nauczyciela paladynów. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj poświęcony list i porozmawiaj z bratem Sammuelem w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(3102, 'koKR', 'Zaszyfrowany list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią Jorika, jednego z naszych miejscowych nauczycieli. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj zaszyfrowany list i porozmawiaj z Jorikiem Kerridanem w stajni za Opactwem Północnych Włości.', '', '', '', '', '', '', 0),
(3103, 'koKR', 'Uświęcony list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią kapłanki Anetty, naszej miejscowej nauczycielki kapłanów. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj uświęcony list i porozmawiaj z kapłanką Anettą w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(3104, 'koKR', 'List z glifami', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią Kheldena, naszego miejscowego nauczyciela magów. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj list z glifami i porozmawiaj z Kheldenem Bremenem w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(3105, 'koKR', 'Skażony list', 'Poproszono mnie, żebym ci to przekazał, gdy tylko wrócisz z obozów koboldów, $N. Wygląda na list zapieczętowany pieczęcią Drusilli, jednej z naszych miejscowych nauczycielek. Przeczytaj go, zanim zajmiesz się czymkolwiek innym tu, w opactwie.', 'Przeczytaj skażony list i porozmawiaj z Drusillą La Salle obok Opactwa Północnych Włości.', '', '', '', '', '', '', 0),
(3861, 'koKR', 'KO-KO!', '„Ko... ko... ko... KOKOODAK!$B$BKo... ko... ko.”$B$BKura spogląda na ciebie, a potem zaczyna drapać pazurami ziemię. Masz wrażenie, że wypisuje jakieś słowo, ale nie wiesz jakie. Czy to może być... S-A-L-D-E-A-N? Zanim zdążysz zapytać, kura odwraca się i wraca do swoich spraw.', 'Znajdź specjalną karmę dla kur i wróć do zaprzyjaźnionej kury. Gdy ją znajdziesz, zrób /cheer w jej stronę, zanim spróbujesz dać jej specjalną karmę dla kur.', '', 'Wróć do kury.', '', '', '', '', 0),
(3903, 'koKR', 'Milly Osworth', '$N, $gpokazałeś:pokazałaś;, że można na tobie polegać. I że nie boisz się ubrudzić rąk, co?$B$BMam przyjaciółkę, Milly Osworth, która ma kłopoty. Stoi ze swoim wozem po drugiej stronie opactwa, niedaleko stajni. Na pewno przydałaby się jej para takich rąk jak twoje.', 'Porozmawiaj z Milly Osworth.', '', '', '', '', '', '', 0),
(3904, 'koKR', 'Plony Milly', 'Banda rozbójników, Nieskorni, wtargnęła do Winnic Północnych Włości, kiedy zbierałam winogrona! Zgłosiłam to straży Północnych Włości i zapewnili mnie, że się tym zajmą, ale... boję się o swoje winogrona! Jeśli Nieskorni ich nie ukradną, to obawiam się, że nasi strażnicy je stratują, przeganiając tych zbirów.$B$BProszę, musisz mi pomóc! Większość winogron zebrałam do wiader, ale zostawiłam je w winnicach na południowym wschodzie.$B$BPrzynieś mi te wiadra! Ocal moje plony!', 'Przynieś 8 skrzynek plonów Milly do Milly Osworth w Opactwie Północnych Włości.', '', 'Wróć do Milly Osworth w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(3905, 'koKR', 'Wykaz winogron', 'Skoro moje plony są uratowane, zanieś ten wykaz winogron bratu Nealsowi. Zarządza zapasami jadła i napitków w Północnych Włościach i na pewno ucieszy się, że ma świeże winogrona.$B$BBrata Nealsa znajdziesz w opactwie, w dzwonnicy... tam lubi kosztować swoje wino.', 'Zanieś wykaz winogron bratu Nealsowi w Opactwie Północnych Włości.', '', '', '', '', '', '', 0),
(5261, 'koKR', 'Eagan Skórołup', 'Eagan Skórołup szuka kogoś, kto zapoluje dla niego na chore wilki. To dobra wiadomość, bo ostatnio w Dolinie Północnych Włości widujemy coraz więcej chorych wilków.$B$BJeśli cię to interesuje, porozmawiaj z Eaganem. Znajdziesz go przy bocznej ścianie opactwa, po lewej.', 'Porozmawiaj z Eaganem Skórołupem.', '', '', '', '', '', '', 0),
(5545, 'koKR', 'Wiązka kłopotów', 'Mam prawdziwy kłopot. Zbliża się termin dostawy drewna, a czasu mam coraz mniej. Wilki i niedźwiedzie na północ stąd przegoniły moich robotników od wiązek drewna, które już narąbali.$B$BRozmawiałam już z zastępcą Rainerem o przepędzeniu zwierząt, ale potrzebuję kogoś, kto zbierze dla mnie drewno. Jeśli przyniesiesz mi osiem wiązek drewna, może jeszcze zdążę na czas.', 'Przynieś 8 wiązek drewna Raelen do obozu drwali we Wschodniej Dolinie.', '', 'Wróć do nadzorczyni Raelen w obozie drwali we Wschodniej Dolinie w Kniei Elwynn.', '', '', '', '', 0),
(5623, 'koKR', 'W łaskach Światłości', 'Witaj ponownie, $gmłody kapłanie:młoda kapłanko;. Nadszedł czas, byś $gpoznał:poznała; naszą wiarę głębiej. Gdy skończysz wszystkie swoje sprawy tu, w Północnych Włościach, odszukaj kapłankę Josettę w Złotych Włościach. Ma cię jeszcze wiele nauczyć i słyszała, że coraz mocniej kroczysz ścieżkami Światłości. Nie może się doczekać dalszych nauk.', 'Porozmawiaj z kapłanką Josettą w Kniei Elwynn.', '', '', '', '', '', '', 0),
(5624, 'koKR', 'Szaty Światłości', 'Zwykle wyznaczam wyznawcom Światłości niewielką próbę, by sprawdzić ich umiejętności. Chcę zobaczyć, czy są godni nosić swoje pierwsze szaty – znak, że Kościół otwarcie uznaje $gkapłana:kapłankę; i $ggo:ją; wspiera.$B$BAle tym razem sytuacja jest nieco inna. Jeden z mieszkańców Złotych Włości widział rannego strażnika przy jeziorze na wschód stąd. Nazywa się Roberts. Znajdź go, ulecz, wzmocnij jego ciało i wróć tutaj. Jeśli to dla mnie zrobisz, uznam twoją próbę za zaliczoną.', 'Znajdź strażnika Robertsa i ulecz jego rany Pomniejszym leczeniem (ranga 2). Następnie obdarz go Słowem mocy: Wytrwałość i wróć do kapłanki Josetty w Złotych Włościach.', '', 'Wróć do kapłanki Josetty w Kniei Elwynn.', 'Ulecz i wzmocnij strażnika Robertsa', '', '', '', 0),
(5805, 'koKR', 'Witaj!', 'Witaj w World of Warcraft!$B$BW ramach szczególnego podziękowania za zakup Edycji Kolekcjonerskiej World of Warcraft oddaj ten bon podarunkowy Merissie Stilwell w Złotych Włościach. Otrzymasz w zamian prezent: małego towarzysza, który będzie ci towarzyszyć w poszukiwaniu przygód i chwały.$B$BJeszcze raz dziękujemy i życzymy miłego pobytu w World of Warcraft!$B', 'Zanieś bon podarunkowy ze Złotych Włości Merissie Stilwell w Złotych Włościach.', '', '', '', '', '', '', 0),
(7677, 'koKR', 'Wymiana białego ogiera', '', '', '', 'Wróć do Katie Hunter w Kniei Elwynn.', '', '', '', '', 0),
(7678, 'koKR', 'Wymiana izabelowatego konia', '', '', '', 'Wróć do Katie Hunter w Kniei Elwynn.', '', '', '', '', 0),
(7937, 'koKR', 'Czeka cię szczęście...', '„Twoje szczęście czeka na ciebie we Wschodniej Dolinie”.$B$BPrzepowiednia, którą wręczył ci Sayge, jest w dotyku lekko ciepła. Gdy mocno ją ściskasz, widzisz obraz obozu drwali we Wschodniej Dolinie w Kniei Elwynn. Skupiając się na obrazie, dostrzegasz stóg siana stojący obok stajni.$B', 'Udaj się do obozu drwali we Wschodniej Dolinie w Kniei Elwynn i odszukaj swoje szczęście.', '', '', '', '', '', '', 0),
(7961, 'koKR', 'Psotne kłóliki!', 'Te kłóliki mnożą się bez opamiętania. Trzeba coś z tym zrobić!$b$bPomóż nam, $n, jesteś naszą jedyną nadzieją.', 'Zbierz 10 pechowych łapek kłólików od psotnych kłólików.', '', 'Wróć do Jonathana LeCrafta na Wyspie Projektantów.', '', '', '', '', 0),
(7962, 'koKR', 'Skórki kłólików', 'Chcę skórki królików LeCrafta. Zdobądź je z królików LeCrafta.$b$bTo ważne!', 'Przynieś 3 skórki królików LeCrafta Jonowi LeCraftowi.', '', 'Wróć do Jonathana LeCrafta na Wyspie Projektantów.', '', '', '', '', 0),
(14032, 'koKR', 'Porządki w obozie koboldów', 'Twoje pierwsze zadanie polega na oczyszczeniu terenu, $N. Klan koboldów zagnieździł się w lasach na północy. Udaj się tam i walcz z koboldzimi szkodnikami, które napotkasz. Przetrzeb ich szeregi, abyśmy pewnego dnia mogli wypędzić ich z Północnych Włości.', 'Zabij 8 koboldzich szkodników, a następnie wróć do marszałka McBride\'a.', '', 'Wróć do marszałka McBride\'a.', '', '', '', '', 0),
(14079, 'koKR', 'Naucz się jeździć w Kniei Elwynn', 'Tę ulotkę reklamującą naukę jazdy i sprzedaż wierzchowców przysłał Randal Hunter.$B$BRandala można znaleźć w obozie drwali we Wschodniej Dolinie w Kniei Elwynn, przy drodze prowadzącej na wschód od Wichrogrodu.', 'Zanieś ulotkę Randalowi Hunterowi do obozu drwali we Wschodniej Dolinie w Kniei Elwynn.', '', 'Wróć do Randala Huntera nad Jeziorem Kamiennego Kopca w Kniei Elwynn.', '', '', '', '', 0),
(25415, 'koKR', 'Szerzenie słowa', 'Witaj w naszym sadzie, $N. Każdy tutaj pracuje na swoje utrzymanie. Niektórzy doglądają drzew owocowych. Inni odpowiadają za nasze prace budowlane. Jeszcze inni szerzą nasze przesłanie wśród ludzi i myślę, że od tego dobrze będzie ci zacząć.$B$BWeź tę tablicę. Jest na niej krótkie przesłanie o naszej wierze. Nosząc ją, odwiedź Garnizon Zachodniego Potoku na południowy zachód stąd, rynek w Złotych Włościach tuż na wschód oraz Dolinę Bohaterów w Wichrogrodzie.', 'Nosząc wiadomość o końcu świata, odwiedź Garnizon Zachodniego Potoku, Dolinę Bohaterów w Wichrogrodzie i rynek w Złotych Włościach.', '', 'Wróć do nadzorczyni Sylandry w Sadzie nad Lustrzanym Jeziorem.', 'Szerz przesłanie w Garnizonie Zachodniego Potoku', 'Szerz przesłanie w Dolinie Bohaterów', 'Szerz przesłanie w Złotych Włościach', '', 0),
(25416, 'koKR', 'Plan Mistrza', 'Dobrze się tu odnajdujesz, $N, ale jesteśmy czymś więcej niż codziennymi obowiązkami i szerzeniem przesłania. Na pewno trochę o tym $gsłyszałeś:słyszałaś;, gdy do nas $gdołączyłeś:dołączyłaś;.$B$BJak wiesz, ten świat się kończy, a nieprzygotowani zginą w męczarniach.$B$BOtrzymaliśmy dar – szansę, by stać się kimś większym i potężniejszym. Nadzorca Talathor przygotowuje rytuał przy ołtarzu tuż na północ od sadu. Zaczekaj tam na niego i dowiedz się więcej o swoich nowych braciach i siostrach.', 'Dowiedz się więcej o planach kultu przy ołtarzu w północnej części Sadu nad Lustrzanym Jeziorem.', '', 'Wróć do nadzorczyni Sylandry w Sadzie nad Lustrzanym Jeziorem.', 'Objawienie Cho\'galla', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(6, 'koKR', 'Ha, $gdopadłeś:dopadłaś; go! $goddałeś:oddałaś; Elwynn wielką przysługę i $gzasłużyłeś:zasłużyłaś; na sowitą nagrodę!', 0),
(7, 'koKR', 'Dobra robota, $gobywatelu:obywatelko;. Te koboldy to złodzieje i tchórze, ale w dużej liczbie stanowią dla nas zagrożenie. A ludzie z Wichrogrodu nie potrzebują kolejnego zagrożenia.$B$BZa ich pokonanie masz moją wdzięczność.', 0),
(11, 'koKR', 'Widzę, że nie $gpróżnowałeś:próżnowałaś;! Dziękujemy ci, $N.', 0),
(15, 'koKR', 'Nie podoba mi się, że w naszej kopalni jest tyle koboldów. Nic dobrego z tego nie wyniknie. Proszę, weź to jako zapłatę, a kiedy będziesz $ggotowy:gotowa;, porozmawiaj ze mną ponownie. Chciałbym, żebyś jeszcze raz $gwrócił:wróciła; do kopalni...', 0),
(16, 'koKR', 'Dzięki, $N! I wracaj, jeśli zechcesz znowu pohandlować.', 0),
(18, 'koKR', 'Widzę, że wracasz z chustami. Armia Wichrogrodu docenia twoją pomoc.', 0),
(21, 'koKR', 'Po raz kolejny $gzasłużyłeś:zasłużyłaś; na mój szacunek i wdzięczność Armii Wichrogrodu. W kopalni mogą jeszcze być koboldy, ale wyślę na nie innych. Mamy dla ciebie kolejne zadania.', 0),
(33, 'koKR', 'Ponure to było zadanie, $gprzyjacielu:przyjaciółko;, ale $gdotrzymałeś:dotrzymałaś; swojej części umowy.\n\nMam tu parę rzeczy, które mogą ci się przydać – wybieraj!', 0),
(35, 'koKR', 'Tak, murloki osiedliły się w strumieniach wschodniego Elwynn i wokół nich. Nie wiemy, po co tu przybyły, ale są agresywne i przynajmniej trochę rozumne.', 0),
(37, 'koKR', 'Choć ze zwłok zdarto większość rzeczy, obok leży medalion z wyrytymi słowami: „Piechur Malakai Stone”.', 0),
(39, 'koKR', 'Hmm, te wieści są niepokojące. Nasza obrona i tak jest już rozciągnięta do granic możliwości, a utrata Rolfa i Malakaia z rąk tych murloków jeszcze pogorszyła nasze położenie.$B$BJeśli nic się nie zmieni, do końca tygodnia walki dotrą do Złotych Włości!', 0),
(40, 'koKR', 'Tak, rozmawiałem z Remym. Szanuję go jako kupca, choć wszystkie doniesienia o murlokach na wschodzie były w najlepszym razie mgliste.$B$BPrzyjmuję twoje obawy do wiadomości, ale dopóki nie dostanę wojskowego raportu o zagrożeniu ze strony murloków, nie możemy sobie pozwolić na wysłanie kolejnych żołnierzy na wschód.', 0),
(45, 'koKR', 'Na szyi zwłok znajdujesz metalowy medalion z wygrawerowanymi słowami: „Piechur Rolf Hartford”.', 0),
(46, 'koKR', 'Masz płetwy? Świetnie! Marszałek Dughan niepokoi się sytuacją z murlokami we wschodnim Elwynn, a ja chciałbym mu powiedzieć, że wszystko wraca pod kontrolę.$b$bTwoje czyny w tym pomogły.', 0),
(47, 'koKR', 'Dzięki za pył, $N. Oto twoja zapłata i... oto upominek od moich wspólników. Może ci się przydać... przydać.', 0),
(52, 'koKR', 'Wielkie dzięki za pomoc, $N. Coś w lesie musi sprawiać, że te zwierzęta stały się takie zuchwałe.$B$BCokolwiek to jest, oby tam zostało.', 0),
(54, 'koKR', 'Cóż, jest tu napisane, że $gotrzymałeś:otrzymałaś; status tymczasowego zastępcy u marszałków Wichrogrodu. Gratulacje.$b$bI powodzenia – dbanie o bezpieczeństwo Elwynn to nie piknik... zwłaszcza że większość armii zajmuje się Bóg wie czym dla Bóg wie którego szlachcica!$b$bW tych mrocznych czasach trudno nadążyć za polityką...', 0),
(59, 'koKR', 'Ach, dziękuję za znacznik. Wybierz śmiało zbroję, którą chcesz.$b$bPowodzenia i niech ta zbroja dobrze ci służy.', 0),
(60, 'koKR', '$GPolowałeś:Polowałaś; na koboldy, co? Dzięki za świece, $N, a oto twoja nagroda...', 0),
(61, 'koKR', 'Oto twoja zapłata... a skoro już tu jesteś, rozejrzyj się! Na pewno mamy jakąś miksturę albo inny drobiazg, który ci się przyda.', 0),
(62, 'koKR', 'To złe wieści. Co następne, smoki?!? Będziemy musieli wzmocnić patrole przy tej kopalni. Dzięki za twój trud, $N. I zaczekaj chwilę... może mam dla ciebie kolejne zadanie.', 0),
(69, 'koKR', 'Stalvan? Rzeczywiście brzmi znajomo.', 0),
(70, 'koKR', 'Masz tupet, że to tu przynosisz.', 0),
(71, 'koKR', '$GPotwierdziłeś:Potwierdziłaś; moje obawy, $N. Murloki to zagrożenie, którego nie możemy lekceważyć.', 0),
(74, 'koKR', 'Ledwie mogę odczytać te litery. Ale ten charakter pisma przypomina mi coś, co widziałem, zanim wzrok tak mi się pogorszył.', 0),
(75, 'koKR', '$GZnalazłeś:Znalazłaś; ją!', 0),
(76, 'koKR', 'Mówisz, że w Kopalni Jaspisowej Żyły są koboldy? Przeklęte! Sytuacja pogarsza się z minuty na minutę!$B$BDziękuję za raport, $N. Ale wolałbym, żeby wieści, które przynosisz, były dobre.', 0),
(78, 'koKR', 'Na Światłość! Pewnie, że rozpoznaję ten charakter pisma.', 0),
(83, 'koKR', 'Ach, ładne chusty, choć trochę szorstkie...$b$bProszę bardzo!', 0),
(84, 'koKR', 'Mmm, pycha! Ten placek jest najlepszy!$b$bChyba wraca mi pamięć...', 0),
(85, 'koKR', 'Co $gzgubiłeś:zgubiłaś;? No ja tam żadnego naszyjnika nie brałem, bo nie jestem żaden złodziej!$b$bMoże i wiem, kto to zrobił, ale... <uśmiech>... za bardzo mi burczy w brzuchu, żeby pamiętać.', 0),
(86, 'koKR', 'Choć to mięso dzika jest twarde, jak się je dość długo poddusi, wychodzi z niego naprawdę smaczny placek!', 0),
(87, 'koKR', 'Och, $gznalazłeś:znalazłaś; go! Dziękuję, dziękuję ci, $gmój drogi:moja droga;!$B$BProszę, weź to. Należało do mojego męża, a on zawsze mówił, że przynosi szczęście. Gdyby tylko nie zapomniał tego, wyruszając na ostatnią wyprawę! *pociąga nosem*', 0),
(88, 'koKR', 'Dzięki niebiosom! Ta świnia tak urosła, że zjadłaby nam całe zbiory! Dziękuję, $N.$b$bA teraz, czy któraś z tych rzeczy ci odpowiada?', 0),
(94, 'koKR', 'Umieszczasz Glif Azory na kamieniu. Przywiera do niego... i słyszysz dobywający się z niego bezcielesny głos Theocritusa:$B$BMasz moją wdzięczność, $N. Możesz teraz rozmawiać ze mną przez ten glif, a ja być może będę mieć dla ciebie kolejne zadania... gdy już zgłębię myśli mojego rywala.', 0),
(106, 'koKR', 'Ach! Nie zniosę tej rozłąki. Muszę się z nią zobaczyć!!', 0),
(107, 'koKR', 'Serce mi się kraje, gdy myślę o tych dwóch biednych duszach, Maybell i Tommym Joe. Pamiętam, jak sam byłem kiedyś młody i zakochany.$b$bMuszę coś zrobić, żeby im pomóc! Niech pomyślę...', 0),
(109, 'koKR', 'Ach, więc to mój przyjaciel cię przysłał? Jak miło.$B$BCóż, monarchia Wichrogrodu porzuciła naszą sprawę. Teraz to Milicja Ludowa musi chronić tę ziemię przed zepsuciem. Jeśli nasza sprawa cię interesuje, mogę wykorzystać twoje umiejętności bojowe w imię wolności.', 0),
(111, 'koKR', 'Dopóki nasze rodziny są skłócone, Tommy Joe i Maybell nie mają przed sobą wielkiej przyszłości, ale... może uda nam się ich połączyć choć na chwilę.$B$BHm, co by tu zrobić...', 0),
(112, 'koKR', 'Masz je. Brawo! A teraz chwileczkę, przyrządzę miksturę...', 0),
(114, 'koKR', 'Och... rety! Mam wyrzuty sumienia, że oszukuję rodzinę, ale moje uczucia do Tommy\'ego Joe są zbyt silne, żeby je zignorować.$b$bDziękuję, $N. Wypiję ten trunek, gdy tylko będę mieć okazję, i wymknę się do ukochanego.$b$bA dla ciebie... proszę, weź to.', 0),
(118, 'koKR', 'He, więc stary Verner potrzebuje podków, tak!?!', 0),
(119, 'koKR', 'Dziękuję, to mi naprawdę pomoże.$b$bAle co to? Argus przysłał liścik ze skrzynką... Co?? Argus chce, żebym mu ZAPŁACIŁ? Phi!$b$bCóż, $N, dziękuję za pomoc.', 0),
(123, 'koKR', 'Hm... słyszałem o tym „Kolekcjonerze”, ale nie wiem, dla kogo pracuje. Dziękuję za harmonogram. Pomoże nam rozwikłać tę zagadkę.', 0),
(147, 'koKR', '$GZnalazłeś:Znalazłaś; go? Dobra robota, $N. Już nigdy nie będzie „kolekcjonował” z kopalń Elwynn!$B$BA ten pierścień, który $gznalazłeś:znalazłaś;, jest ciekawy... to pierścień członkowski dawnej Gildii Kamieniarzy z Wichrogrodu. Po co zwykłemu złodziejowi pierścień gildii rzemieślniczej i czemu złodzieje z Bractwa Nieskornych zbierają pieniądze z naszych kopalń?$B$BTrudne pytania. Mam nadzieję, że pewnego dnia poznamy odpowiedzi.', 0),
(176, 'koKR', 'Ha! Dobra robota! Już zaczynałem myśleć, że nikt nie powali tego potwora!$B$BProszę, $N. I dzięki – przez tego gnola głowa bolała mnie tak, jakby była wielkości Iglicy Czarnej Góry!', 0),
(178, 'koKR', 'Masz moją wdzięczność, $N. Wysłałem tę wiadomość do wisiorów Cienioskórych przed wieloma tygodniami i myślałem, że się nie udało. Ale wygląda na to, że zaklęcie dotarło przynajmniej do niektórych wisiorów, choć ze sporym opóźnieniem.$B$BZ czasem mam nadzieję nauczyć się przesyłać przez wisiory atak, który unieruchomi każdego gnola z Cienioskórych, który go nosi.$B$BAle zanim to będzie możliwe, obawiam się, że czeka mnie jeszcze wiele badań.', 0),
(239, 'koKR', 'Marszałek Dughan cię przysłał, co? Cóż, nie jesteś z armii, ale skoro przysłał cię Dughan, to mi wystarczy!$b$bNasze położenie jest, delikatnie mówiąc, napięte. Mam nadzieję, że nam pomożesz.', 0),
(249, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Pokonując czarnoksiężnika Morgantha, $guratowałeś:uratowałaś; Wichrogród przed wielkim niebezpieczeństwem.$B$BZ pokorą ofiarowuję ci tę nagrodę. Życzyłbym ci pokoju, gdyby nastały czasy pokoju.$B$BZamiast tego życzę ci szczęścia w próbach i zwycięstwa w nadchodzących bojach.', 0),
(344, 'koKR', 'Pan Sheaf zastanawia się, gdzie jest jego księga? Cóż, to trochę krępujące. Mam tę księgę, ale wciąż robię odpis i nie jestem jeszcze gotów oddać oryginału!', 0),
(345, 'koKR', 'Potrzebujesz czego?? Może nie $gzauważyłeś:zauważyłaś;, ale jesteśmy zajęci umacnianiem obrony Jeziernych Włości i naprawianiem szkód po ostatnich napaściach orków. Jeśli potrzebujesz rudy żelaza z Rethbanu, musisz ją zdobyć $gsam:sama;!', 0),
(346, 'koKR', 'To ta! Dziękuję ci, $N. Niech Światłość jasno świeci nad twoim ciałem i duchem!', 0),
(347, 'koKR', 'Och, wspaniale! Z tej rudy zrobię barwnik i będę mógł dokończyć odpis „Naprężeń żelaza”.$B$BDziękuję, $N!', 0),
(783, 'koKR', 'Ach, dobrze. $gKolejny ochotnik:Kolejna ochotniczka;. Ostatnio zgłasza się was wielu.$B$BMam nadzieję, że to wystarczy.$B$BZiemiom ludzi zagraża wróg z zewnątrz, a tak wiele naszych sił wysłano za granicę. To z kolei pozwala zepsutym i bezprawnym bandom rosnąć w siłę w naszych granicach.$B$BToczymy walkę na wielu frontach, $N. Przygotuj się na długą kampanię.', 0),
(1097, 'koKR', '$GPrzyszedłeś:Przyszłaś; pomóc mi z dostawą? Bardzo dobrze!', 0),
(1638, 'koKR', 'Oho! Napij się ze mną, $N. Z zewnątrz wyglądasz na $gtwardziela:twardzielkę;, ale zobaczmy, czy twój żołądek zniesie kilka kufli najmocniejszego trunku w „Świni i Gwizdku”!!$B$BA może... $gprzyszedłeś:przyszłaś; na lekcję?', 0),
(1666, 'koKR', 'Kto tam?$B$BBurlguard, to ty?$B$BMusisz podejść trochę bliżej. Oczy już nie te.$B$BJak tak $gpodchodziłeś:podchodziłaś;, myślałem, że to gnol!', 0),
(1667, 'koKR', 'Świetnie, $gznalazłeś:znalazłaś; ją! Bałem się, że przepadła na zawsze i Nieskorni będą jej używać, podszywając się pod urzędnika Wichrogrodu. Cóż, dzięki tobie już do tego nie dojdzie.$B$BOto broń, której używałem, gdy byłem marszałkiem. Utrzymywałem ją w świetnym stanie – wybieraj!', 0),
(1685, 'koKR', 'Najwyższy czas, żebyś się $gpojawił:pojawiła;. Choć może powinienem był posłać po ciebie kogoś bardziej kompetentnego niż Remen.$B$BNieważne.$B$BZbyt długo obywasz się bez szkolenia, a nieszkolony czarnoksiężnik rzadko długo utrzymuje głowę na karku.', 0),
(1786, 'koKR', 'Dziękuję ci, $gbracie:siostro;.$B$BSkoro władasz Symbolem Życia, mogę chyba założyć, że przysłał cię Duthorian albo Gazin?$B$BPadłem od zaklęć magów Nieskornych, gdy razem z Gazinem próbowaliśmy wydrzeć im ich plany. Zdołałem wytrzymać wystarczająco długo, by Gazin mógł uciec, ale w końcu ich magia mnie przemogła.$B$BAle $gzdołałeś:zdołałaś; mnie przywrócić: nie każdy potrafi posługiwać się Symbolem, $N. To dobrze wróży, że $gzdołałeś:zdołałaś; napełnić go mocą własnej wiary.', 0),
(1787, 'koKR', 'Wspaniale! Udało ci się i $guratowałeś:uratowałaś; Henzego. Światłość z pewnością jest z tobą, $N!', 0),
(1860, 'koKR', 'To ciebie przysłano, żebyś $gpomógł:pomogła; mi w moim zadaniu, $N? Dobrze. Miło widzieć młodych magów, którzy chętnie wspierają naszą sprawę...$b$bJaką sprawę, pytasz? W swoim czasie, $gmłodzieńcze:młoda damo;. Dowiesz się... w swoim czasie.', 0),
(1919, 'koKR', '$N, mam dla ciebie misję, tu, w Dzielnicy Magów. Słuchaj uważnie, bo nie ma czasu do stracenia.', 0),
(2158, 'koKR', 'Odpoczynek i relaks dla zmęczonych i zmarzniętych – oto nasze motto! Proszę, usiądź przy ogniu i daj odpocząć zmęczonym kościom.$B$BMoże chcesz skosztować naszego wyśmienitego jadła i napitków?', 0),
(2205, 'koKR', '$GZnalazłeś:Znalazłaś; mnie – a sądząc po twoim wyglądzie, bieganina i poszukiwania mocno nadwyrężyły twoje siły, i to zarówno psychiczne, jak i fizyczne.$B$BChcesz, żeby Renzik zaprowadził cię do karczmy, czy jesteś $ggotów:gotowa; do roboty?', 0),
(2300, 'koKR', '$GGotowy:Gotowa; do roboty czy musisz się najpierw zdrzemnąć?', 0),
(2998, 'koKR', 'Pięknie tu, w Wichrogrodzie, prawda?$B$BNie $gmogłeś:mogłaś; wybrać lepszej chwili, $N.', 0),
(3100, 'koKR', 'Rozgość się, poznaj okolicę i wracaj do mnie, kiedy tylko będziesz potrzebować szkolenia. Będę tu dniem i nocą.$B$BRycerze Srebrnej Dłoni sporo zrobili, by to miejsce było w miarę bezpieczne, ale kiedy poznasz innych mieszkańców, przekonasz się, że każdy ma jakiś kłopot i przyda mu się pomoc – taka, jakiej może udzielić $c. Powodzenia.', 0),
(3101, 'koKR', 'Tymczasem musisz wiedzieć jeszcze jedną czy dwie rzeczy. Dla wielu w tej krainie jesteś symbolem – postępuj zgodnie z tym. Święta Światłość jaśnieje w tobie i dostrzegą to zarówno twoi sojusznicy, jak i wrogowie.$B$BPoza tym, w miarę jak będziesz zyskiwać mądrość i moc, będziesz $gmusiał:musiała; szkolić się w nowych umiejętnościach. Tu wkraczam ja. Kiedy poczujesz, że $gzdobyłeś:zdobyłaś; tu, w Północnych Włościach, nieco doświadczenia, wróć do mnie, a nauczę cię tego, na co moim zdaniem będziesz $ggotów:gotowa;. Powodzenia!', 0),
(3102, 'koKR', 'Przekonasz się, że sporo ekip chętnie skorzysta z naszych umiejętności, Cailel. Poszukiwacze przygód, WW:7... u licha, nawet Bractwo Nieskornych nie pogardziłoby szpiegiem czy dwoma w Wichrogrodzie. Ale zapamiętaj jedno: jesteś $gpanem samego siebie:panią samej siebie;. Nie daj się nikomu zmusić do czegoś, czego nie chcesz robić! Zresztą to my trzymamy wszystkie karty... przynajmniej zanim gra się skończy. Rozumiesz, co mam na myśli?$b$bW każdym razie chciałem się tylko przedstawić i dać ci znać, że jestem tu, gdybyś $gpotrzebował:potrzebowała; szkolenia. Wpadaj, kiedy chcesz.', 0),
(3103, 'koKR', 'Gdy nabierzesz doświadczenia, wróć do mnie, a zrobię, co w mojej mocy, by przekazać ci swoją wiedzę. Do tego czasu idź ze współczuciem w sercu i niech mądrość będzie twoim przewodnikiem. Pamiętaj: świat staje się lepszy tylko wtedy, gdy ty go takim uczynisz.', 0),
(3104, 'koKR', 'Ha, wiedziałem, że mój liścik nie odwiedzie cię od twojej ścieżki. A więc jesteś $ggotów:gotowa;? $gGotowy:Gotowa; przyjąć swój los? $gGotowy:Gotowa; rzucić wyzwanie bogom i wszelkim innym siłom, które staną ci na drodze do wiedzy i potęgi?$B$BNie będę kłamał, $N: będą się ciebie bać tak samo, jak będą cię szanować. Ale wiedz też, że będę tu, gdy będziesz potrzebować szkolenia. Po prostu odszukaj mnie, gdy staniesz się $gpotężniejszy:potężniejsza;.', 0),
(3105, 'koKR', 'W miarę jak będziesz rosnąć w siłę, pojawią się pokusy – musisz zawsze pamiętać o panowaniu nad sobą. Nie będę kłamać: zepsucie może dopaść każdego adepta tajemnych sztuk, zwłaszcza tego, kto ma do czynienia z istotami z Wypaczonej Otchłani. Bądź $gcierpliwy:cierpliwa; i $grozważny:rozważna;... ale nie pozwól, by to stłumiło twoje ambicje.$B$BGdy staniesz się $gpotężniejszy:potężniejsza;, wróć do mnie, a nauczę cię więcej o naszych metodach.', 0),
(3861, 'koKR', '„KOKOODAK!!!”$B$BKura zaczyna łapczywie dziobać karmę, którą jej $gpołożyłeś:położyłaś;.$B$BPo chwili rozgląda się, jakby czymś zaskoczona. Niespokojnie przestępuje z nogi na nogę. Czyżby ta kura miała znieść jajko? Chyba lepiej zajrzeć pod nią.', 0),
(3903, 'koKR', 'Och, to zastępca Willem kazał ci ze mną porozmawiać? To odważny człowiek i zawsze chętnie pomaga, ale obowiązki trzymają go w Opactwie Północnych Włości, a obawiam się, że mój dzisiejszy kłopot go przerasta.$b$bMoże ty mi pomożesz?', 0),
(3904, 'koKR', 'Och, dziękuję ci, $N! $GUratowałeś:Uratowałaś; moje plony! Mam nadzieję, że $gpokazałeś:pokazałaś; kilku z tych Nieskornych, że nie mogą tu siać zamętu.$b$bMoże brakuje nam ostatnio strażników, ale na szczęście mamy bohaterów takich jak ty, którzy nas chronią!', 0),
(3905, 'koKR', 'Zobaczmy...$b$bO rety! Winogrona Milly ocalały! Kiedy powiedziała mi, że rozbójnicy opanowali jej winnice, omal nie popadłem w rozpacz, ale moja wiara w Światłość nie osłabła!$b$bA dzięki twojej odwadze mamy winogrona na nowe wino! Niech Światłość cię błogosławi, $N, i ma cię w swojej opiece!', 0),
(5261, 'koKR', 'Zgadza się. Szukam kogoś, kto zapoluje dla mnie na wilki! To ty?', 0),
(5545, 'koKR', 'Doskonale! Dzięki tobie powinnam zdążyć z zamówieniem na czas. W dowód wdzięczności chciałabym dać ci trochę monet jako rekompensatę za fatygę.$b$bDziękuję i żegnaj.', 0),
(5623, 'koKR', 'Cieszę się, że $gprzybyłeś:przybyłaś;, $N. Mamy wiele do omówienia na temat twojej przyszłości i twojej ścieżki w Światłości.', 0),
(5624, 'koKR', 'Doskonale, $N. Z jeszcze jednym zdrowym strażnikiem, który pomaga miastu, będziemy o tyle bezpieczniejsi. Cieszę się, że już uczysz się mądrze korzystać ze swoich zdolności. Gdy tylko poczujesz, że jesteś $ggotów:gotowa; na dalsze szkolenie, wróć do mnie. Ale na razie weź tę szatę. Dzięki niej inni będą wiedzieć, że należysz do naszego zakonu. Jeśli nie chcesz jej nosić, nic nie szkodzi. Później czekają cię kolejne próby, a do nich ta szata nie jest potrzebna.', 0),
(5805, 'koKR', 'Jesteś $gnaprawdę wyjątkowym bohaterem:naprawdę wyjątkową bohaterką;, $N. Witamy cię w świecie Azeroth i ofiarujemy ci jeden z tych wyjątkowych prezentów!', 0),
(7937, 'koKR', 'Szybkie przeszukanie stogu siana odsłania ukrytą w nim szkatułkę! Wygląda na to, że $gznalazłeś:znalazłaś; swoje szczęście!', 0),
(14079, 'koKR', 'No to co, zaczynamy twoje szkolenie z jazdy dla uczniów?', 0),
(25415, 'koKR', 'Dobra robota, $N. Na początku może być niezręcznie, ale przywykniesz do publicznego głoszenia naszej wiary. To jeden ze sposobów, by pamiętać o naszym obowiązku niesienia prawdy innym. Musimy dawać nadzieję wszystkim, bo wszyscy razem stajemy w obliczu końca tego świata.', 0),
(25416, 'koKR', 'Teraz, gdy rozumiesz plan Mistrza, musisz przygotować się do odegrania swojej roli w jego urzeczywistnieniu.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(6, 'koKR', '$GZnalazłeś:Znalazłaś; szopę Garricka? Czy w końcu pozbyliśmy się tego łotra?', 0),
(7, 'koKR', 'Jak idą łowy, $N? $GZnalazłeś:Znalazłaś; i $gpokonałeś:pokonałaś; te szkodniki?', 0),
(11, 'koKR', 'Witaj, $N. $GZabijałeś:Zabijałaś; gnole...?', 0),
(15, 'koKR', '$GByłeś:Byłaś; w kopalni? Jesteś $ggotów:gotowa; złożyć raport?', 0),
(16, 'koKR', 'Praca na roli wzmaga pragnienie, a ja zawsze szukam orzeźwiającej wody źródlanej.$B$BJeśli jakąś masz, chętnie się wymienię.', 0),
(18, 'koKR', '$GZebrałeś:Zebrałaś; już dla mnie te chusty?', 0),
(21, 'koKR', 'Wiem, że to krwawa robota, $N, ale od niej zależy bezpieczeństwo Północnych Włości. Jesteś $ggotów:gotowa; złożyć raport?', 0),
(33, 'koKR', 'Hej, $N. Jak idzie polowanie na chore młode wilki?', 0),
(46, 'koKR', 'Jak idą łowy, $N?', 0),
(47, 'koKR', 'Psst! Masz dla mnie ten złoty pył... dla mnie?', 0),
(52, 'koKR', '$GZabiłeś:Zabiłaś; te wilki i niedźwiedzie?', 0),
(54, 'koKR', 'Masz wieści od McBride\'a? Północne Włości to ogródek w porównaniu z Knieją Elwynn, ale ciekawe, co marszałek McBride ma do zameldowania.$b$bDaj mi jego dokumenty...', 0),
(59, 'koKR', 'Armia Wichrogrodu zleciła mi zaopatrywanie swoich ludzi w zbroje z płótna i skóry.$b$bJeśli masz dla mnie znacznik, chętnie coś dla ciebie zrobię.', 0),
(60, 'koKR', '$GZebrałeś:Zebrałaś; już te świece?', 0),
(61, 'koKR', 'Och, przesyłka od mojego brata? Wspaniale! Szczęście naprawdę mi dziś sprzyja!', 0),
(62, 'koKR', 'Co masz do zameldowania, $N? $GByłeś:Byłaś; w Kopalni Dalekiej Głębi?', 0),
(70, 'koKR', 'Co tam masz? Daj mi na to zerknąć...', 0),
(71, 'koKR', 'Witaj, $N. $GOdkryłeś:Odkryłaś;, co się stało z Rolfem i Malakaiem?', 0),
(74, 'koKR', 'Co tam masz? Nie widzę. Mam bardzo słaby wzrok. Daj mi to do rąk.', 0),
(75, 'koKR', '$GZnalazłeś:Znalazłaś; tę stronę, o której mówiłem, $N?', 0),
(76, 'koKR', 'Witaj, $N. Co masz do zameldowania? $GZbadałeś:Zbadałaś; Kopalnię Jaspisowej Żyły?', 0),
(78, 'koKR', 'To marszałek Haggard cię przysłał? Czemu od razu nie mówisz?$B$BAch, stary dobry Haggard. Biedak niedługo całkiem oślepnie. W każdym razie pokaż, co tam masz.', 0),
(83, 'koKR', 'Kończy mi się len, $N. Masz coś dla mnie?', 0),
(84, 'koKR', 'Uch... umieram z głodu! Masz dla mnie ten placek, $N?', 0),
(86, 'koKR', 'Nie uważam, że to w porządku karmić chłopaka, który w ogóle ukradł mi naszyjnik, ale jeśli tylko tak odzyskam to, co moje, niech tak będzie!$b$bMasz tę dziczyznę?', 0),
(87, 'koKR', 'Witaj, $N. $GZnalazłeś:Znalazłaś; mój naszyjnik?', 0),
(88, 'koKR', '$GWidziałeś:Widziałaś; ją już? $GDopadłeś:Dopadłaś; ją?', 0),
(94, 'koKR', 'Ten posąg lwa stoi tu od dziesięcioleci i samotnie strzeże osławionej Wieży Ilgalara.$B$BU podstawy posągu jest wgłębienie, w którym można by osadzić klejnot albo glif...', 0),
(106, 'koKR', 'Co masz?? Maybell to światło mojego szarego życia. Szybko, pokaż mi jej list!', 0),
(107, 'koKR', 'Masz liścik od „Babci” Stonefield, tak? Nie widziałem Mildred od lat! Ciekawe, co ma do powiedzenia...', 0),
(109, 'koKR', 'I... i jak??', 0),
(111, 'koKR', 'Nie mogę się doczekać, jak zareagują moi przyjaciele!$B$BNigdy się tego nie spodziewają', 0),
(112, 'koKR', 'Masz te kryształowe wodorosty? Maybell na pewno nie może się doczekać spotkania ze swoim ukochanym...', 0),
(114, 'koKR', '$GDostarczyłeś:Dostarczyłaś; mój list Tommy\'emu Joe? Co powiedział??', 0),
(118, 'koKR', 'Co takiego? Verner cię przysłał, mówisz? No to dawaj jego liścik. I MÓW GŁOŚNIEJ!', 0),
(119, 'koKR', 'Świetnie, $gwróciłeś:wróciłaś;! Masz podkowy?', 0),
(123, 'koKR', 'Co?!? Od miesięcy nie mamy żadnych naszych ludzi w kopalniach Elwynn!$B$BPokaż mi ten liścik...', 0),
(147, 'koKR', '$GZnalazłeś:Znalazłaś; Kolekcjonera? $GOdkryłeś:Odkryłaś;, dla kogo pracuje?', 0),
(176, 'koKR', 'Tak, Wyżer dał się mocno we znaki mnie i moim ludziom. Masz coś do zameldowania w sprawie tej bestii?', 0),
(178, 'koKR', 'Mówisz, że przemówiłem do ciebie przez wisior? Hmm... daj mi go, żebym mógł go zbadać.', 0),
(249, 'koKR', 'Pospiesz się, $N, zanim moje obawy przed tym, że Morganth rozszerzy swoją władzę, się ziszczą!', 0),
(346, 'koKR', 'Udało ci się znaleźć księgę?', 0),
(347, 'koKR', 'Masz rudę z Rethbanu?', 0),
(1667, 'koKR', 'Masz moją odznakę? Nie chcę nawet myśleć, jakich szkód mógłby nią narobić Martwozęby Jack.', 0),
(1787, 'koKR', 'Czy Henze jest bezpieczny, $N? Udało ci się?$B$BZ twoją biegłością w walce i mocą Światłości Czuwanie Bohaterów jest chyba bezpieczne przed zagrożeniem ze strony Nieskornych, ale to już ocenią król i jego doradcy.', 0),
(2205, 'koKR', 'W czym mogę pomóc?', 0),
(3100, 'koKR', 'Ach, $gdostałeś:dostałaś; mój list, $N... dobrze.$B$BOstatnio do Elwynn napłynęło sporo wojowników – co dobrze wróży Wichrogrodowi, ale źle koboldom i Nieskornym w okolicy.', 0),
(3101, 'koKR', 'W końcu! Spotykamy się twarzą w twarz, $gbrat z bratem:brat z siostrą;. Witam cię w Północnych Włościach. Przez krótki czas będzie to twój dom, póki nie poznasz wszystkich tajników, ale wiedz, że Wichrogród jest niedaleko i prędzej czy później twoja ścieżka cię tam zaprowadzi. Do tego czasu bądź $gcierpliwy:cierpliwa;... $gRycerzu:Rycerko; Srebrnej Dłoni.', 0),
(3102, 'koKR', '$GDotarłeś:Dotarłaś; tu w jednym kawałku i nie wygląda na to, żeby wiele osób cię widziało. Jak dla mnie wystarczy. Nie lubię zwracać na siebie uwagi... tu, z tyłu, jest miło i cicho. Na pewno rozumiesz.$b$bJakieś kłopoty? Cieszę się, że nie. Wkrótce się to zmieni.', 0),
(3103, 'koKR', 'Ach, nareszcie jesteś. Wiedziałam, że trafisz do mnie. Święta Światłość jaśnieje nad tobą i nad ścieżką, którą $gobrałeś:obrałaś;. Nastały ciężkie czasy – Płonący Legion wciąż jest obecny w Azeroth, cały Kalimdor szuka nowych sposobów obrony przed własnymi utrapieniami, a do ciebie należy nieść pomoc tak wielu, jak tylko zdołasz.', 0),
(3104, 'koKR', 'Witaj, $N. Jestem Khelden. Mogę coś dla ciebie zrobić?', 0),
(3105, 'koKR', 'Ach, więc $gprzybyłeś:przybyłaś;, i to w samą porę, $N. Przed chwilą kręcili się tu strażnicy i dziwnie mi się przyglądali... żałośni prostaczkowie.', 0),
(3861, 'koKR', 'Kura wpatruje się w ciebie ciemnymi, zimnymi oczami. Czeka na ciebie głodna.$B$B„KOKOOODAK!$B$BKo... ko... ko.”', 0),
(3904, 'koKR', 'Masz moje plony, $N?', 0),
(3905, 'koKR', 'Widzę, że dopisuje ci humor! Chodź! Usiądź i napij się!', 0),
(5545, 'koKR', 'Termin się nie oddala. Proszę, pospiesz się i zbierz te wiązki drewna.', 0),
(5624, 'koKR', 'Jak być może już wiesz, nasza magia uzdrawiania jest niezbędna do przetrwania naszego ludu w tych ciężkich czasach – zwłaszcza dla poszukiwaczy przygód i bohaterów, którzy chwytają za broń i magię, by odpierać tak wiele różnych zagrożeń.$B$BDobrze zrobisz, jeśli zawsze będziesz pamiętać, jak ważna jest ta umiejętność. W połączeniu z Wytrwałością sprawia, że twoi towarzysze są w walce znacznie skuteczniejsi, bo wytrzymują o wiele więcej ciosów.$B$BNie pozwól nikomu lekceważyć potęgi twojej magii.', 0),
(5805, 'koKR', 'Witaj! Miło cię poznać!$B$BWidzę, że masz specjalny bon. Daj mi go, a dam ci coś w zamian.', 0),
(7937, 'koKR', 'Ten stóg siana wygląda jak ten z twojej wizji.', 0),
(14079, 'koKR', 'Ach, $gdostałeś:dostałaś; mój list? Dobrze.', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(234, 0, 'koKR', 'Plugawe zepsucie wkradło się do Zachodniego Skraju. Gdy pełniłem swój obowiązek na polach bitew Lordaeronu, te uczciwe farmy zostały opanowane i zamienione w kryjówki zbirów i morderców. Milicja Ludowa potrzebuje twojej pomocy.', 0),
(237, 0, 'koKR', 'Same kłopoty w tych stronach. Próbowałem przekonać tego głupca Saldeana, żeby się wynosił, póki może, ale nie chce o tym słyszeć. Ale ja nie jestem głupi. Razem z Verną zwijamy się stąd, jak tylko naprawimy ten wóz.', 0),
(240, 0, 'koKR', 'Ech, trudno tu utrzymać porządek i bez tych wszystkich nowych kłopotów, które wciąż wyskakują! Mam nadzieję, że masz dobre wieści, $n...', 0),
(241, 0, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko;. Nazywam się Remy. Jestem z Rudej Grani na wschodzie i przyjechałem tu szukać interesów, szukać interesów. Masz coś... masz coś??', 0),
(253, 0, 'koKR', 'Aha! Dzień dobry, dzień dobry! Chodź, usiądź i napij się. Masz w oku błysk przedsiębiorczości i myślę, że rozmowa ze mną będzie warta twojego czasu...', 0),
(261, 0, 'koKR', 'Witaj, $gobywatelu:obywatelko;. Wyglądasz na $gczłowieka:kobietę; z celem – masz jakąś sprawę do Armii Wichrogrodu?', 0),
(267, 0, 'koKR', 'Witaj w Mrocznych Włościach. Urzędnik Daltry do usług. Czy mogę w czymś pomóc?', 0),
(273, 0, 'koKR', 'Zamykaj drzwi. Nigdy nie wiadomo, kiedy znów przejadą tędy Mroczni Jeźdźcy.', 0),
(278, 0, 'koKR', 'Witaj, $gszanowny panie:szanowna pani;. Usiądź i zjedz coś, jeśli jesteś $ggłodny:głodna;. Nie przejmuj się, że wyglądam na zajętą robótką – słucham cię...', 0),
(294, 0, 'koKR', 'Witaj, wędrowcze. Może i mam słaby wzrok, ale kroki wojownika czy maga wyczuję z odległości mili. Przez lata z dumą broniłem Wichrogrodu, ale kiedy zawiodły mnie oczy, musiałem przejść na emeryturę.', 0),
(313, 0, 'koKR', 'Witaj w Wieży Azory. Jestem Theocritus.$B$BMasz do mnie jakąś sprawę? A może... to ja mam sprawę do ciebie?', 0),
(341, 0, 'koKR', 'Nie mam czasu na pogaduszki, $N. Muszę odbudować ten most, zanim przyjdą deszcze. Każdy projekt kończyłem na czas i poniżej budżetu i nie zamierzam teraz zacząć się spóźniać.', 0),
(415, 0, 'koKR', 'Hej, $gkolego:proszę pani;, możesz mi w czymś pomóc? Jestem w naprawdę PODŁYM położeniu...', 0),
(823, 0, 'koKR', 'Witaj. Normalnie chodziłbym po ulicach i pilnował mieszkańców Wichrogrodu, ale wielu strażników Wichrogrodu walczy w innych krainach. No i jestem tu, jako zastępca, wyznaczam nagrody, choć wolałbym być na patrolu...', 0),
(1440, 0, 'koKR', 'Nigdzie nie znajdziesz większej skarbnicy wiedzy niż w Bibliotece Królewskiej w Wichrogrodzie!', 0),
(6171, 0, 'koKR', 'Mrok, który otacza nasze ziemie, wiele razy wystawi cię na próbę, $N. Ale żebyś zawsze $gbył gotowy:była gotowa;, będziemy często zlecać ci zadania, dzięki którym będziesz w szczytowej formie.$B$BIdź ze Światłością i pozostań $gprawy:prawa;.', 0),
(6946, 0, 'koKR', 'Mathias znalazł mnie na Pustkowiach, gdzie spółka Gitgeszeft zostawiła mnie na pewną śmierć. Gdyby nie on, zostałbym karmą dla drapieżców.', 0);
