INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(15, 'koKR', 'Witaj, Morganie,$B$Binteres w Złotych Włościach kwitnie, i to tak bardzo, że nie mam czasu wysyłać ci żadnych dostaw!  $B$BZleciłem osobie, która przynosi ten liścik, dostarczenie ci paczki dużych woskowych świec (wiesz, tych, które koboldy lubią nosić na głowach). $B$BPodziękuj, proszę, tej osobie w naszym imieniu i uczciwie jej zapłać.', 0),
(18, 'koKR', 'Szanowny Panie,\n\nWieść o tym, że poszukuje Pan nauczyciela dla swoich dzieci, dotarła do mnie tu, w Złotych Włościach, gdzie tymczasowo mieszkam w karczmie „Lwia Duma”. Z powodu niefortunnego obrotu spraw w regionie musiałem porzucić stanowisko dyrektora szkoły w Księżycowym Potoku. Proszę przyjąć moją kandydaturę na nauczyciela Pańskich dzieci. Dyrektor Crillian z Akademii może w razie potrzeby poświadczyć moje umiejętności.', 0),
(19, 'koKR', 'Przybędę spotkać się z Panem osobiście, gdy ustaną zimowe deszcze, a drogi znów będą nadawać się do podróży.\n\nDo tego czasu pozostaję\n\nStalvan Mgłopłaszcz ze Srebrzystego Boru', 0),
(20, 'koKR', '. . .Giles, chłopiec, wydaje się nieco krnąbrny i jego edukacja będzie wyzwaniem. Za to starsza córka, Tilloa, jest wyjątkowo bystra. Nie mogłem też nie zauważyć jej urzekającej urody. Jest właśnie u progu kobiecości. Podobno pan domu zaaranżował jej małżeństwo na przyszły rok. Ale odbiegam od tematu. W tym tygodniu będę towarzyszyć rodzinie w letnim domku niedaleko obozu drwali we Wschodniej Dolinie w Elwynn, blisko Gór Rudej Grani. Mam nadzieję, że tam napiszę więcej.', 0),
(21, 'koKR', '. . .najdziwniejsze i nieopanowane uczucie. Nigdy jeszcze nie czułem się tak jak dziś. Gdy pomagałem Gilesowi w lekcji historii, Tilloa zajmowała się ogrodem kwiatowym. Po kilku minutach weszła do środka, włożyła mi w otwartą dłoń szkarłatną begonię i uśmiechnęła się do mnie tak, że serce zadrżało mi w piersi. . . .', 0),
(25, 'koKR', 'Tommy Joe –$B$Bz każdą godziną twojej nieobecności moje serce więdnie. Och, gdyby tylko nasi bliscy potrafili spojrzeć ponad głupie krzywdy, które sobie wyrządzili, i zrozumieć, że jedyną prawdziwą zbrodnią jest nienawiść. Nienawiść pożera, a ja się boję, że w tych coraz mroczniejszych czasach zawładnie czymś więcej niż tylko naszymi rodzinami.$B$BGdyby to zrozumieli, moglibyśmy wreszcie być razem. Na ten dzień czekam i dla tego dnia żyję.$B$BTwoja ukochana$BMaybell', 0),
(26, 'koKR', 'Witaj, Williamie,\n\nod naszej ostatniej rozmowy minęły lata, ale ufam, że ty i twój brat macie się dobrze, a wasza apteka kwitnie.\n\nMuszę cię prosić o przysługę, Williamie. Krótko mówiąc, mój wnuk Tommy Joe stracił serce dla młodej Maybell Maclure. I choć się uwielbiają... nasze rodziny, cóż, nasze rodziny są od lat skłócone.\n', 0),
(28, 'koKR', 'Argusie, $B$Bjak wiesz, tonę w zamówieniach na naprawy od armii. Nie narzekam na pracę, ale kończą mi się zapasy żelaza.$B$BNie mam dość żelaza na podkowy. Wiem, że zawsze trzymasz duży zapas – chciałbym pożyczyć 50 par podków, dopóki nie dostanę kolejnej dostawy żelaza.$B$BZ wdzięcznością,$B-Verner', 0),
(29, 'koKR', 'Do skrzyni przyczepiono liścik. Brzmi:\n\n„Vernerze – przykro mi, że Ruda Grań ma takie kłopoty. Oto podkowy, których potrzebujesz. Zapłać mi, proszę, 100 srebrników, gdy tylko będziesz mógł.”\n\n„A jeśli wolisz, możesz mi zapłacić łuskami z brzuchów czarnych smoczych piskląt (słyszałem, że w Górach Rudej Grani smoczych piskląt jest pełno). Ponieważ jesteśmy przyjaciółmi... wystarczą 4 łuski. Dzięki – Argus”', 0),
(78, 'koKR', 'Ten znacznik pancerza można wymienić na jedną część skórzanego lub płóciennego pancerza w domu Timberlainów w obozie drwali we Wschodniej Dolinie.', 0),
(79, 'koKR', 'Poniżej opisano sposób i harmonogram zbiórki złota Nieskornych z kopalń Elwynn do naszej kwatery głównej w Zachodnim Skraju. Harmonogram zbiórki: niedziela: 12:30, środa: 12:30. W każdy wyznaczony dzień złoto wydobyte w kopalniach Elwynn będzie zbierane na polu dyniowym Brackwellów. Agenta odpowiedzialnego za te zbiórki, „Poborcę”, rozpoznacie po grawerowanym pierścieniu, który nosi. Pierścieniu, który sam mu dałem. ', 0),
(209, 'koKR', 'RAPORT: Koboldy$B$BAktywność koboldów w okolicy Doliny Północnych Włości wzrosła. Obozują na północ od opactwa i w Kopalni Echowej Grani w niepokojącej liczbie. Zebrałem paladynów, wojowników i innych miejscowych, by pomogli mi pozbyć się tego robactwa.$B$BPostępy są dobre. Będę składać kolejne raporty w miarę potrzeby.', 0),
(210, 'koKR', 'RAPORT: Złodzieje$B$BBardziej niepokojąca od koboldów jest ludzka banda złodziei, która pojawiła się w dolinie. Noszą czerwone chusty i nazywają siebie bractwem. Taki poziom organizacji może oznaczać kłopoty, zarówno tutaj, jak i w całej Kniei Elwynn.$B$BZidentyfikowaliśmy jednego z ich przywódców – niejakiego Garricka Cichostopego – i mamy nadzieję wkrótce postawić go przed sądem.', 0),
(211, 'koKR', 'RAPORT: Wilki$B$BW Północnych Włościach zgłasza się coraz więcej ataków zwierząt. Eagan uważa, że wilki w dolinie przepłoszono tu z Kniei Zmierzchu.$B$BChoć wilki rzadko polują na ludzi, ich liczba doprowadziła do kilku incydentów z rolnikami. Zaginęło też wiele sztuk bydła.', 0),
(212, 'koKR', 'WYRÓŻNIENIE:$B$BOkaziciel tych dokumentów otrzymuje status zastępcy w Armii Wichrogrodu, gdyż służył Północnym Włościom z zapałem i wyróżnił się w tej służbie. Jestem przekonany, że osoba ta okaże się przydatna w Kniei Elwynn.$B$Bpodpisano:$B-marszałek Douglas McBride, $BArmia Wichrogrodu, Północne Włości', 0),
(218, 'koKR', 'Obawiam się, że wojna między Stonefieldami a Maclure\'ami zabije rodzące się uczucie Tommy\'ego Joe i Maybell, a w takich czasach jak te – gdy wisi nad nami widmo złych wieści i pogłosek o wojnie – młodość i miłość trzeba pielęgnować.$b$bA więc przysługa: proszę, byś wykorzystał swoje umiejętności i przyrządził miksturę lub eliksir, który pomoże tym młodym zakochanym odnaleźć się nawzajem.$b$bDziękuję ci, Williamie. I proszę, gdy znajdziesz chwilę wolną od pracy, odwiedź mnie. Pośmiejemy się trochę ze starych czasów.$b$b-Mildred', 0),
(250, 'koKR', 'Oddział z kwatery głównej Nieskornych nawiąże kontakt z Poborcą, po czym ten przekaże zebrane złoto. Dopilnujcie, by wszystko odbyło się bez zakłóceń i z zachowaniem najwyższej dyskrecji. Za przekazanie złota odpowiada Poborca, ale ostatecznie każdy członek Bractwa Nieskornych odpowiada za to, by swoją rolę odegrał uważnie i zdyscyplinowanie. ', 0),
(251, 'koKR', 'Pamiętajcie, bracia, byliśmy kiedyś dumnymi rzemieślnikami. Nasze obecne obowiązki będziemy wypełniać z tą samą precyzją, z jaką uprawialiśmy dawny fach. -EVC ', 0),
(811, 'koKR', 'Plan został wprawiony w ruch. Zajmijcie tę niegdyś wspaniałą twierdzę wiary, Czuwanie Bohaterów, jako nasz obóz, a gdy dacie znać, że miejsce jest odpowiednio przygotowane, zaczniemy przerzucać do was posiłki z Zachodniego Skraju. Mieszkańcy i żołnierze Wichrogrodu niemal zapomnieli o tej okolicy, więc będzie to doskonały punkt wypadowy dla naszych ataków. Nieskorni odbiorą Wichrogród! Czekam na odpowiedź. ', 0),
(1392, 'koKR', 'Bracie Nealsie,$B$Bmoje winogrona są uratowane! $N, okaziciel tego wykazu, $gwszedł:weszła; do mojej winnicy pełnej zbirów i $gzebrał:zebrała; winogrona, których ja nie mogłam. Choć Nieskorni wciąż krążą za rzeką, udało się ocalić niemal całe zbiory.$B$BMożesz dodać do swoich zapasów pełen ładunek koszy winogron.$B$BNiech Światłość ma nas w opiece,$B-Milly Osworth', 0),
(2012, 'koKR', 'Kil\'jaeden cisnął lodową skorupę Ner\'zhula z powrotem do świata Azeroth. Stwardniały kryształ przeciął nocne niebo i rozbił się na opustoszałym arktycznym kontynencie Północnej Grani, zagłębiając się w lodowcu Lodowej Korony. Zamarznięty kryształ, powykrzywiany i poorany gwałtownym upadkiem, zaczął przypominać tron, a mściwy duch Ner\'zhula wkrótce się w nim poruszył.', 0),
(2013, 'koKR', 'Z wnętrza Mroźnego Tronu Ner\'zhul zaczął sięgać swoją ogromną świadomością i dotykać umysłów rdzennych mieszkańców Północnej Grani. Bez większego wysiłku zniewolił umysły wielu tamtejszych istot, w tym lodowych trolli i dzikich wendigo, i wciągnął ich złych pobratymców w swój rosnący cień. Jego moce psychiczne okazały się niemal nieograniczone, a on wykorzystał je do stworzenia niewielkiej armii, którą umieścił w krętych labiryntach Lodowej Korony. ', 0),
(2014, 'koKR', 'Gdy Król Lisz opanowywał swoje rosnące zdolności pod nieustannym nadzorem upiornych władców, odkrył odległą ludzką osadę na skraju rozległych Smoczych Pustkowi. Pod wpływem kaprysu Ner\'zhul postanowił wypróbować swoje moce na niczego niepodejrzewających ludziach. ', 0),
(2015, 'koKR', 'Ner\'zhul zesłał na arktyczne pustkowie zarazę nieumarłości, która zrodziła się w głębi Mroźnego Tronu. Kierując zarazą wyłącznie siłą woli, skierował ją prosto na ludzką wioskę. W ciągu trzech dni wszyscy w osadzie nie żyli, lecz wkrótce potem martwi wieśniacy zaczęli powstawać jako ożywione zwłoki. Ner\'zhul czuł ich dusze i myśli, jakby były jego własnymi.', 0),
(2016, 'koKR', 'Szalejąca w jego umyśle kakofonia sprawiła, że Ner\'zhul stał się jeszcze potężniejszy, jak gdyby ich dusze dawały mu tak bardzo potrzebny pokarm. Odkrył, że kierowanie poczynaniami zombi i prowadzenie ich do dowolnego celu to dziecinna igraszka.', 0),
(2017, 'koKR', 'W kolejnych miesiącach Ner\'zhul kontynuował eksperymenty ze swoją zarazą nieumarłości, podporządkowując sobie każdego ludzkiego mieszkańca Północnej Grani. Jego armia nieumarłych rosła z każdym dniem, a on wiedział, że zbliża się czas prawdziwej próby.', 0),
(2022, 'koKR', 'Mijały miesiące, a kolejnych orkowych jeńców zganiano do obozów internowania. Gdy obozy zaczęły pękać w szwach, Przymierze musiało budować nowe na równinach na południe od Gór Alterak. Aby należycie utrzymać i zaopatrywać coraz liczniejsze obozy, król Terenas nałożył na państwa Przymierza nowy podatek. ', 0),
(2023, 'koKR', 'Ten podatek, w połączeniu z narastającymi napięciami politycznymi wokół sporów granicznych, wywołał powszechne niepokoje. Zdawało się, że kruchy pakt, który w najczarniejszej godzinie zjednoczył ludzkie królestwa, w każdej chwili może się rozpaść.', 0),
(2024, 'koKR', 'Pośród politycznego zamętu wielu strażników obozów zaczęło dostrzegać niepokojącą zmianę u swoich orkowych więźniów. Próby ucieczki, a nawet bójki między samymi orkami, z czasem stawały się coraz rzadsze. Orkowie stawali się coraz bardziej obojętni i ospali.', 0),
(2025, 'koKR', ' Choć trudno było w to uwierzyć, orkowie – niegdyś uważani za najbardziej agresywną rasę, jaką kiedykolwiek widziano w Azeroth – całkowicie utracili wolę walki. Dziwny letarg wprawiał przywódców Przymierza w konsternację i nadal zbierał żniwo wśród szybko słabnących orków. ', 0),
(2026, 'koKR', 'Niektórzy przypuszczali, że ten zagadkowy letarg wywołała jakaś dziwna choroba, na którą zapadali tylko orkowie. Arcymag Antonidas z Dalaranu wysunął jednak inną hipotezę. Badając to niewiele, co zdołał znaleźć o historii orków, Antonidas dowiedział się, że orkowie od pokoleń znajdowali się pod niszczącym wpływem demonicznej mocy.', 0),
(2027, 'koKR', ' Przypuszczał, że moce te zepsuły orków jeszcze przed ich pierwszą inwazją na Azeroth. Demony najwyraźniej zatruły krew orków, a w zamian te brutale zyskały nienaturalnie wzmożoną siłę, wytrzymałość i agresję.', 0),
(2028, 'koKR', 'Antonidas uznał, że zbiorowy letarg orków nie jest w istocie chorobą, lecz skutkiem odstawienia przez całą rasę niestabilnej magii czarnoksięskiej, która uczyniła z nich budzących grozę, żądnych krwi wojowników. ', 0),
(2029, 'koKR', 'Choć objawy były oczywiste, Antonidas nie potrafił znaleźć lekarstwa na obecny stan orków. Co więcej, wielu jego kolegów magów, a także kilku znamienitych przywódców Przymierza, twierdziło, że szukanie lekarstwa dla orków byłoby nierozważne. Pozostawiony z zagadką stanu orków, Antonidas doszedł do wniosku, że ich uleczenie musiałoby mieć charakter duchowy.', 0),
(2093, 'koKR', 'W tym czasie nieumarła Plaga w zasadzie przemieniła Lordaeron i Quel\'Thalas w toksyczne Plagowiska. Pozostało zaledwie kilka ognisk oporu sił Przymierza. Jedną z takich grup, złożoną głównie z wysokich elfów, dowodził ostatni z dynastii Słońcobieżców: książę Kael\'thas. ', 0),
(2094, 'koKR', 'Kael, sam będący biegłym czarodziejem, zaczął nieufnie spoglądać na chylące się ku upadkowi Przymierze. Wysokie elfy opłakiwały utratę ojczyzny i postanowiły nazwać się krwawymi elfami na cześć swojego poległego ludu. Lecz gdy walczyły, by powstrzymać Plagę, ogromnie cierpiały z powodu odcięcia od Słonecznej Studni, która dawała im moc. ', 0),
(2095, 'koKR', 'Rozpaczliwie szukając lekarstwa na uzależnienie swojego ludu od magii, Kael zrobił rzecz nie do pomyślenia: przyjął dziedzictwo Wysoko Urodzonych przodków swojego ludu i sprzymierzył się z Illidanem i jego nagami w nadziei, że znajdzie nowe źródło magicznej mocy, którym mógłby się karmić. Pozostali dowódcy Przymierza potępili krwawe elfy jako zdrajców i wygnali je na zawsze.', 0),
(2096, 'koKR', 'Nie mając dokąd pójść, Kael i jego krwawe elfy podążyli za Lady Vash do Rubieży, by pomóc w walce ze strażniczką Maiev, która ponownie pojmała Illidana. Połączonymi siłami nag i krwawych elfów zdołali pokonać Maiev i wyrwać Illidana z jej rąk. Z Rubieży jako bazy Illidan zebrał siły do drugiego uderzenia na Króla Lisza i jego twierdzę w Lodowej Koronie. ', 0),
(2097, 'koKR', 'Ner\'zhul, Król Lisz, wiedział, że jego czas jest krótki. Uwięziony w Mroźnym Tronie, podejrzewał, że Kil\'jaeden wyśle swoich sługów, by go zniszczyli. Zaklęcie Illidana naruszyło Mroźny Tron, przez co Król Lisz z każdym dniem tracił moc. Rozpaczliwie próbując się ocalić, wezwał do siebie swojego największego śmiertelnego sługę: rycerza śmierci, księcia Arthasa.', 0),
(2098, 'koKR', 'Choć słabość Króla Lisza wysysała jego moce, Arthas był uwikłany w wojnę domową w Lordaeronie. Połowa sił nieumarłych, prowadzona przez banshee Sylwanę Bieżywiatr, przeprowadziła zamach stanu, by przejąć władzę nad imperium nieumarłych. Wezwany przez Króla Lisza Arthas musiał zostawić Plagę w rękach swojego zastępcy, Kel\'Thuzada, podczas gdy wojna rozlewała się po Plagowiskach.', 0),
(2099, 'koKR', 'Ostatecznie Sylwana i jej zbuntowani nieumarli (znani jako Porzuceni) przejęli zrujnowaną stolicę Lordaeronu. Wznosząc własną twierdzę pod zniszczonym miastem, Porzuceni poprzysięgli pokonać Plagę i przepędzić Kel\'Thuzada wraz z jego sługami z tych ziem.', 0),
(2100, 'koKR', 'Osłabiony, lecz zdeterminowany, by ocalić swojego pana, Arthas dotarł do Północnej Grani tylko po to, by zastać tam czekające na niego nagi i krwawe elfy Illidana. Wraz ze swoimi nerubiańskimi sojusznikami ścigał się z siłami Illidana, by dotrzeć do lodowca Lodowej Korony i obronić Mroźny Tron.', 0),
(2432, 'koKR', 'Nigdy nie byłem bardziej dumny z przynależności do fachu niż przez ostatnie kilka lat. Zapotrzebowanie na skrytobójców, szpiegów i zwiadowców nigdy nie było większe. Można by pomyśleć, że wojna przynosi większy popyt, ale co zaskakujące, to nie w czasie wojny najlepiej prosperujemy, tylko teraz – gdy pokój zaczyna się sypać.$B$BPowiedziano mi, że będziesz w okolicy i zechcesz się czegoś nauczyć. Kiedy znajdziesz czas, odwiedź mnie przy stajniach za opactwem.$B$B-Jorik Kerridan, nauczyciel łotrów ', 0),
(2439, 'koKR', 'Powiedz mi, czy $gsłyszałeś:słyszałaś; już krzyk orka? Czy $gbroniłeś:broniłaś; swojego domu przed gnolami, które chcą rozszarpać ci gardło? Tak, brzmi brutalnie, prawda?$B$BCóż, będziesz potrzebować mojej pomocy, jeśli chcesz chronić swoich bliskich. Znajdziesz mnie w opactwie w Północnych Włościach. Moja wiedza nie jest tania, ale jeśli masz dość doświadczenia, nauczę cię wielu stylów walki i ruchów, które pomogą ci odeprzeć zagrożenia dla Wichrogrodu i nie tylko.$B$BLlane Beshere, nauczyciel wojowników', 0),
(2445, 'koKR', 'Magia ma cztery prawa:$B$B   Magia jest potężna.$B   Magia deprawuje.$B   Magia uzależnia.$B   Magia przyciąga mieszkańców Wypaczonej Otchłani do tych, którzy władają tajemną mocą.$B$BNa tych prawach zawsze możesz polegać. Te prawa będą rządzić twoim przeznaczeniem, jeśli zdecydujesz się kroczyć dalej ścieżką maga.$B$BJeśli jesteś na tyle $gnierozsądny:nierozsądna;, by zignorować to ostrzeżenie, przyjdź porozmawiać ze mną w skrzydle bibliotecznym opactwa w Północnych Włościach. Będę czekać na ciebie na górze.$B$B-Khelden Bremen, nauczyciel magów ', 0),
(2449, 'koKR', 'Zbyt często ludzie tacy jak wyznawcy Świętej Światłości straszą tych, których ciekawi prawdziwa moc, wmawiając im, że nie wolno im zgłębiać żadnej formy tajemnej sztuki – a przecież nie wszystko, co pochodzi spoza tego świata, jest złe. Nie wszystkie istoty dążą do panowania nad innymi czy ich zniewolenia. Jeśli masz dość mocy, te same istoty mogą stać się twoimi sługami.$B$BChciałabym porozmawiać z tobą o tym więcej. Odszukaj mnie na cmentarzu po prawej stronie opactwa.$B$B-Drusilla La Salle, nauczycielka czarnoksiężników ', 0),
(2463, 'koKR', 'Mam nadzieję, że ten list zastanie cię w dobrym zdrowiu. Mówię to z wielką dumą, bo niewielu może wyznawać tak głęboką wiarę i zarazem wiedzieć, że należy do najznamienitszych obrońców Azeroth.$B$BZawsze pamiętaj, że przede wszystkim twoim obowiązkiem jest stawać do walki z tymi, którzy chcą skrzywdzić nasz świat i wnieść zepsucie do naszych domów.$B$BPowierzono mi na razie pieczę nad twoim szkoleniem. Gdy będziesz $ggotów:gotowa;, odszukaj mnie w Opactwie Północnych Włości.$B$B-Brat Sammuel, nauczyciel paladynów ', 0),
(2465, 'koKR', 'Twoja więź ze światem i jego więź z tobą są kluczem do twojego sukcesu jako $gkapłana:kapłanki;. Mądrość i współczucie pozwolą ci pomagać tym, którzy naprawdę tego potrzebują. Nadgorliwość i niezdarne decyzje tylko przeszkadzają innym stać się silniejszymi albo wyrządzają krzywdę.$B$BGdy zaczniesz rozumieć, co to znaczy, będziesz potrzebować nowych umiejętności i zaklęć. Tu zaczyna się moja rola: odszukaj mnie w skrzydle bibliotecznym Opactwa Północnych Włości, gdy będziesz $ggotów:gotowa; do szkolenia.$B$B-Kapłanka Anetta, nauczycielka kapłanów', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(10106, 'koKR', 'Nie wiem, co cię opętało, żeby szukać szamana... ale widziałem kogoś, kto pasuje do opisu. Na brzegu w Dolinie Bohaterów przebywa kobieta, która nazywa siebie wieszczką.', 'Nie wiem, co cię opętało, żeby szukać szamana... ale widziałem kogoś, kto pasuje do opisu. Na brzegu w Dolinie Bohaterów przebywa kobieta, która nazywa siebie wieszczką.', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(14393, 'koKR', 'Gratulacje, twój umysł został poszerzony.', 'Gratulacje, twój umysł został poszerzony.', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(16211, 'koKR', 'Ech, i bez tych nowych kłopotów trudno tu utrzymać porządek! Mam nadzieję, że masz dobre wieści, $N...', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50016, 'koKR', 'Witaj. Normalnie patrolowałbym ulice i pilnował mieszkańców Wichrogrodu, ale wielu strażników Wichrogrodu walczy w innych krainach. Dlatego siedzę tutaj jako zastępca i wyznaczam nagrody, choć wolałbym być na patrolu...', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50017, 'koKR', 'Hej, $gprzyjacielu:przyjaciółko;. Jestem Remy.$BPochodzę z Rudej Grani na wschodzie i przyszedłem tu robić interesy, robić interesy. Masz coś... masz coś??', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50018, 'koKR', 'Witaj, $gobywatelu:obywatelko;. Wyglądasz na kogoś, kto ma jakiś cel – masz sprawę do Armii Wichrogrodu?', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50019, 'koKR', 'Same kłopoty w tych stronach. Próbowałem przekonać tego głupca Saldeana, żeby się stąd wynosił, póki może, ale nie chce o tym słyszeć. Ja jednak głupcem nie jestem. Verna i ja zwijamy się stąd, jak tylko naprawimy ten wóz.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50020, 'koKR', 'Plugawe zepsucie wkradło się do Zachodniego Skraju. Kiedy pełniłem swoją powinność na polach bitew Lordaeronu, te uczciwe farmy zostały opanowane i zamienione w kryjówki zbirów i morderców. Milicja Ludowa potrzebuje twojej pomocy.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50021, 'koKR', 'Ciemność, która otacza nasze ziemie, wiele razy wystawi cię na próbę, $N. Ale by mieć pewność, że zawsze będziesz $ggotów:gotowa;, często będziemy powierzać ci zadania, dzięki którym osiągniesz szczyt swoich możliwości.$B$BIdź ze Światłością i trwaj w cnocie.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(50028, 'koKR', 'Aha! Dzień dobry, dzień dobry! Chodź, usiądź i napij się. Masz w oku przedsiębiorczy błysk i myślę, że rozmowa ze mną będzie warta twojego czasu...', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
