INSERT INTO `trainer_locale` (`Id`, `locale`, `Greeting_lang`, `VerifiedBuild`) VALUES
(1, 'koKR', 'Witaj! Czas na trening wojownika?', 0),
(2, 'koKR', 'Witaj! Czas na trening wojownika?', 0),
(3, 'koKR', 'Witaj! Czas na trening paladyna?', 0),
(6, 'koKR', 'Witaj! Czas na trening paladyna?', 0),
(9, 'koKR', 'Witaj! Czas na trening łotrzyka?', 0),
(10, 'koKR', 'Witaj! Czas na trening łotrzyka?', 0),
(11, 'koKR', 'Witaj! Czas na trening kapłański?', 0),
(12, 'koKR', 'Witaj! Czas na trening kapłański?', 0),
(16, 'koKR', 'Witaj! Czas na trening magii?', 0),
(17, 'koKR', 'Witaj! Czas na trening magii?', 0),
(31, 'koKR', 'Witaj! Czas na trening czarnoksięski?', 0),
(32, 'koKR', 'Witaj! Czas na trening czarnoksięski?', 0),
(37, 'koKR', 'Witaj! Mogę cię czegoś nauczyć?', 0),
(60, 'koKR', 'Chcesz się nauczyć, jak z wydobytej rudy robić broń i metalowe pancerze?', 0),
(61, 'koKR', 'Witaj! Mam cię nauczyć, jak ze skór zwierząt robić pancerze?', 0),
(67, 'koKR', 'Dzięki alchemii z zebranych ziół zrobisz mikstury lecznicze i wiele innych.', 0),
(69, 'koKR', 'Szukanie ziół wymaga zarówno wiedzy, jak i instynktu.', 0),
(74, 'koKR', 'Witaj! Mam cię nauczyć, jak ze znalezionego materiału szyć płócienne pancerze?', 0),
(77, 'koKR', 'Mam cię nauczyć, jak z mięsa upolowanych zwierząt przyrządzić ucztę?', 0),
(83, 'koKR', 'Pozwól, że pokażę ci, jak opatrzyć te rany...', 0),
(96, 'koKR', 'Zaklinanie to sztuka ulepszania przedmiotów za pomocą magii.', 0),
(98, 'koKR', 'Mogę cię nauczyć, jak łowić ryby na wędkę.', 0),
(100, 'koKR', 'Ściąganie skóry z ubitej zwierzyny wymaga pewnej ręki.', 0);
