INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(39, 'koKR', 'Gdzie nie spojrzę, widzę złodziei. My, Milicja Ludowa, musimy zwrócić tę ziemię rolnikom.', '', 0),
(40, 'koKR', 'Farmy muszą zostać wyzwolone. Wichrogród mógł porzucić tych ludzi, ale niech mnie diabli, jeśli ja to zrobię.', '', 0),
(44, 'koKR', 'Mieszkańcy Zachodniego Skraju nie wybaczą Wichrogrodowi, że ich porzucił.', '', 0),
(50, 'koKR', 'No dalej, chłopaki, musimy odbudować ten most.', '', 0),
(56, 'koKR', 'Nie mogę uwierzyć, że ten przeklęty wóz się zepsuł. W tej krainie nie ma za grosz szczęścia. . . .', '', 0),
(57, 'koKR', 'Wyniesiemy się stąd, jak tylko naprawię ten wóz. . . .', '', 0),
(58, 'koKR', 'No i jak mam wygonić te mechaniczne paskudztwa z moich pól?', '', 0),
(59, 'koKR', 'Banda zbirów i złodziei nie zmusi mnie do opuszczenia mojej ziemi!', '', 0),
(60, 'koKR', 'Mogli przepędzić wszystkich innych rolników, ale Saldeanowie nigdy nie opuszczą Zachodniego Skraju.', '', 0),
(82, 'koKR', 'Ta mroczna skaza jest fatalna dla interesów.', '', 0),
(84, 'koKR', 'Oby twój kufel, gdy już pełny, napełnił się znowu!', '', 0),
(85, 'koKR', 'Witaj w karczmie „Lwia Duma”. Czuj się jak u siebie!', '', 0),
(86, 'koKR', 'Tyle do zrobienia, tyle do zrobienia! Gdzie ucieka ten czas?', '', 0),
(197, 'koKR', 'Chwała $n! $GObrońcy:Obrończyni; Ludu!', '', 0),
(198, 'koKR', 'Mieszkańcy Zachodniego Skraju oddają cześć – oto $n, $godważny i dzielny obrońca:odważna i dzielna obrończyni; wolności.', '', 0),
(199, 'koKR', 'Trzykrotne hura na cześć $n! Ta ziemia znów będzie nasza!', '', 0),
(282, 'koKR', 'Dziękuję ci, $n. Niech Światłość cię błogosławi, $Gbracie:siostro;, i prowadzi twoją ścieżką.', '', 0),
(683, 'koKR', '%s głęboko wzdycha.', '', 0),
(684, 'koKR', 'Nie znoszę tej części mojej pracy. Och, Knieja Zmierzchu, bądź łaskawa dla biednego Antonia.', '', 0),
(685, 'koKR', 'Starożytności, broń wojenna, rzadkie pancerze. Kto wie, co Antonio będzie miał w tym tygodniu, jeśli nie przyjdziecie zobaczyć?', '', 0),
(686, 'koKR', 'W tym tygodniu może to być oko traszki, a może mapa skarbów. Nie dowiecie się, dopóki nie zajrzycie. Co też może mieć Antonio?', '', 0),
(687, 'koKR', 'Poszukiwacze przygód z całego świata sprzedają rzeczy Antoniowi – przyjdźcie i sami zobaczcie, jakie skarby ma dla was w tym tygodniu.', '', 0),
(688, 'koKR', 'Podróżni i poszukiwacze przygód, spieszcie na rynek i skorzystajcie ze wspaniałych cen Antonia! Zapraszam wszystkich!', '', 0),
(689, 'koKR', 'Witajcie, podróżni Kniei Zmierzchu! Moje niezwykłe towary są przez krótki czas dostępne w Mrocznych Włościach. Pospieszcie się!', '', 0),
(690, 'koKR', 'Zostawcie swoje bitwy i sprawunki, i obejrzyjcie moje niezwykłe towary! Tylko przez krótki czas w Mrocznych Włościach... i chwała za to Światłości.', '', 0),
(691, 'koKR', 'Żegnajcie, mieszkańcy Mrocznych Włości. Do następnego razu...', '', 0),
(692, 'koKR', 'Nareszcie Ruda Grań. Miła odmiana po ciemnej, zimnej mgle Kniei Zmierzchu.', '', 0),
(702, 'koKR', 'Witaj, witaj, Amy. Dobrze znów być w Jeziernych Włościach i widzieć panią.', '', 0),
(704, 'koKR', 'Słuchajcie, słuchajcie! Zatrzymam się tu, w Jeziernych Włościach, tylko na krótko, by sprzedać swoje towary. Spieszcie do ratusza!', '', 0),
(712, 'koKR', 'Nareszcie dotarłem do Jeziernych Włości – przyjdźcie wszyscy i skorzystajcie ze wspaniałych okazji Antonia Perellego.', '', 0),
(713, 'koKR', 'Przedmioty dość potężne, by pomóc w przeprawie przez Knieję Zmierzchu – towary Antonia Perellego są teraz na sprzedaż tu, w Jeziernych Włościach.', '', 0),
(714, 'koKR', 'Miło było znów cię zobaczyć, Amy. Uważaj na siebie, kochana. Ruszam teraz do Złotych Włości.', '', 0),
(716, 'koKR', 'Witajcie, przyjaciele. Dobrze was znów widzieć. Widzę, że wciąż strzeżecie naszych granic. Antonio docenia waszą ciężką pracę.', '', 0),
(717, 'koKR', 'Nie ma za co! Muszę ruszać w drogę... uważajcie na siebie, wszyscy.', '', 0),
(718, 'koKR', 'Witaj znowu, Antonio. Jeszcze raz dziękuję za kapelusz dla mojej żony. Była nim zachwycona.', 'Witaj znowu, Antonio. Jeszcze raz dziękuję za kapelusz dla mojej żony. Była nim zachwycona.', 0),
(719, 'koKR', 'Uważaj na siebie, Antonio.', 'Uważaj na siebie, Antonio.', 0),
(720, 'koKR', 'Och, będę, przyjacielu. Z pewnością będę. Ty też uważaj na siebie.', '', 0),
(721, 'koKR', 'Towary na sprzedaż! Towary na sprzedaż! Obejrzyjcie towary Antonia, zanim będę musiał odjechać, mieszkańcy Złotych Włości.', '', 0),
(722, 'koKR', 'Zapraszam wszystkich! Towary Antonia na sprzedaż. Mogę długo nie wrócić, więc zapraszam wszystkich!', '', 0),
(723, 'koKR', 'Dobrzy ludzie ze Złotych Włości, skorzystajcie z moich niezwykłych cen na rzadkie towary. Przez jakiś czas nie wrócę!', '', 0),
(724, 'koKR', 'Do widzenia, Złote Włości. Wrócę niedługo – może za tydzień.', '', 0),
(726, 'koKR', 'Znane w całej krainie towary Antonia Perellego są teraz na sprzedaż przy Wzgórzu Strażniczym! Wkrótce muszę ruszać dalej, więc się pospieszcie.', '', 0),
(727, 'koKR', 'Trwałe, solidnie wykonane przedmioty na sprzedaż przy Wzgórzu! Zapraszam wszystkich! Czasu jest mało, więc się pospieszcie.', '', 0),
(728, 'koKR', 'Nadszedł czas, bym znów udostępnił swoje towary wszystkim, którzy podróżują w pobliżu Wzgórza Strażniczego! Zapraszam wszystkich!', '', 0),
(729, 'koKR', 'Dziękuję wam wszystkim. Wrócę za mniej więcej tydzień.', '', 0),
(730, 'koKR', 'No to chyba do Mrocznych Włości.', '', 0),
(893, 'koKR', 'Rety, ryby tu wcale nie biorą. Może pójdę nad Kryształowe Jezioro spróbować szczęścia!', '', 0),
(894, 'koKR', 'Kurczę! Tu też nie biorą. Wracam do mojego starego łowiska!', '', 0),
(1242, 'koKR', 'Możesz odejść, $n.', '', 0),
(1851, 'koKR', 'To nie powinno długo potrwać...', '', 0),
(1853, 'koKR', 'Trunek niewidzialności jest gotowy, $n.', '', 0),
(1862, 'koKR', '', 'Raz kozie śmierć...', 0),
(1863, 'koKR', 'Nie zabijać mnie! Nie zabijać mnie!', '', 0),
(1864, 'koKR', 'Jiiiiii! Ja uciekać!', '', 0),
(1865, 'koKR', 'Ach, okazja, by użyć świeżo naostrzonego ostrza.', 'Ach, okazja, by użyć świeżo naostrzonego ostrza.', 0),
(1866, 'koKR', 'Bractwo nie będzie tolerować twoich poczynań.', 'Bractwo nie będzie tolerować twoich poczynań.', 0),
(1867, 'koKR', 'Poczuj potęgę Bractwa!', 'Poczuj potęgę Bractwa!', 0),
(1868, 'koKR', 'Ty nie brać świeczka!', '', 0),
(1870, 'koKR', 'Grrrr... świeże mięso!', '', 0),
(1871, 'koKR', 'Więcej kości do ogryzania...', '', 0),
(2283, 'koKR', 'Dziękuję ci, $gchłopcze:dziewczyno;. Wielkie dzięki.', '', 0),
(2284, 'koKR', 'Dzięki tobie, $n.', '', 0),
(2346, 'koKR', '%s zabiera się do pracy...', '', 0),
(2347, 'koKR', 'Niesamowite! Udało się! $n, mam twój pancerz.', '', 0),
(2353, 'koKR', 'Powodzenia, $n. I nie zapomnij... zdobądź ten zwój, zanim odnajdziesz Gazina.', '', 0),
(2502, 'koKR', 'Witaj, magu. Mam ci przybliżyć dalsze tajniki świata magii?', 'Witaj, magu. Mam ci przybliżyć dalsze tajniki świata magii?', 0),
(2522, 'koKR', 'Interesuje mnie szkolenie maga.', 'Interesuje mnie szkolenie maga.', 0),
(2525, 'koKR', 'Witaj. Jestem gnomem, nauczycielem magów, a ty jesteś magiem.', 'Witaj. Jestem gnomem, nauczycielem magów, a ty jesteś magiem.', 0),
(2526, 'koKR', 'Witaj. Chcesz rady? Zaprzyjaźnij się z magiem! Mamy w zanadrzu parę sztuczek, oj, mamy...', 'Witaj. Chcesz rady? Zaprzyjaźnij się z magiem! Mamy w zanadrzu parę sztuczek, oj, mamy...', 0),
(2544, 'koKR', 'Interesuje mnie szkolenie czarnoksiężnika.', 'Interesuje mnie szkolenie czarnoksiężnika.', 0),
(2545, 'koKR', '', 'To jeszcze nie twój czas. Pomogę ci wrócić do krainy żywych... za pewną cenę.', 0),
(2547, 'koKR', 'Przywróć mnie do życia.', 'Przywróć mnie do życia.', 0),
(2681, 'koKR', '', 'Proszę, $n. Weź skrzynię szkatuł przechowawczych i inkantację manifestacji. Będą ci potrzebne w twojej misji.', 0),
(2749, 'koKR', 'Bank Wichrogrodu', 'Bank Wichrogrodu', 0),
(2750, 'koKR', 'Bank znajduje się w Dzielnicy Handlowej, na północny zachód od bram miasta. Proszę, pokażę ci na mapie.', 'Bank znajduje się w Dzielnicy Handlowej, na północny zachód od bram miasta. Proszę, pokażę ci na mapie.', 0),
(2821, 'koKR', 'Witaj w mojej karczmie, zmęczony wędrowcze. Co mogę dla ciebie zrobić?', 'Witaj w mojej karczmie, zmęczony wędrowcze. Co mogę dla ciebie zrobić?', 0),
(2822, 'koKR', 'Chcę uczynić tę karczmę swoim domem.', 'Chcę uczynić tę karczmę swoim domem.', 0),
(2861, 'koKR', 'No, no... patrzcie, co kot przyniósł... w czym mogę pomóc?', 'No, no... patrzcie, co kot przyniósł... w czym mogę pomóc?', 0),
(2862, 'koKR', 'Potrzebuję szkolenia, Keryn.', 'Potrzebuję szkolenia, Keryn.', 0),
(2864, 'koKR', 'Mistrza gryfów znajdziesz na północno-wschodnim wale z widokiem na Dolinę Bohaterów.', 'Mistrza gryfów znajdziesz na północno-wschodnim wale z widokiem na Dolinę Bohaterów.', 0),
(2876, 'koKR', 'Aaa, szukasz Dungara Długołyka. Ma jedne z najszybszych gryfów po tej stronie Khaz Modan! Znajdziesz go na wałach w Dzielnicy Handlowej.', 'Aaa, szukasz Dungara Długołyka. Ma jedne z najszybszych gryfów po tej stronie Khaz Modan! Znajdziesz go na wałach w Dzielnicy Handlowej.', 0),
(2877, 'koKR', 'Chcesz się przelecieć na gryfie, co? Dungar trzyma swoje ptaki na wale w Dzielnicy Handlowej. Tylko pamiętaj, żeby się mocno trzymać! ', 'Chcesz się przelecieć na gryfie, co? Dungar trzyma swoje ptaki na wale w Dzielnicy Handlowej. Tylko pamiętaj, żeby się mocno trzymać! ', 0),
(2878, 'koKR', 'Gryfy, co? Nigdy nie przepadałem za tymi bestiami, ale każdy ma swój gust.\nDungara Długołyka znajdziesz na wale w Dzielnicy Handlowej.', 'Gryfy, co? Nigdy nie przepadałem za tymi bestiami, ale każdy ma swój gust.\nDungara Długołyka znajdziesz na wale w Dzielnicy Handlowej.', 0),
(2879, 'koKR', 'Aldwina Laughlina znajdziesz w Punkcie informacyjnym Wichrogrodu w Dzielnicy Handlowej.', 'Aldwina Laughlina znajdziesz w Punkcie informacyjnym Wichrogrodu w Dzielnicy Handlowej.', 0),
(2880, 'koKR', 'Zakładasz gildię, co? No to powodzenia!\nPorozmawiaj z Aldwinem Laughlinem w Punkcie informacyjnym Wichrogrodu. To w Dzielnicy Handlowej, zaraz po wejściu od strony Doliny Bohaterów.', 'Zakładasz gildię, co? No to powodzenia!\nPorozmawiaj z Aldwinem Laughlinem w Punkcie informacyjnym Wichrogrodu. To w Dzielnicy Handlowej, zaraz po wejściu od strony Doliny Bohaterów.', 0),
(2881, 'koKR', 'Aaa, w takim razie szukasz Punktu informacyjnego Wichrogrodu. To pierwszy budynek po lewej, gdy przejdziesz przez główną bramę od strony Doliny Bohaterów.', 'Aaa, w takim razie szukasz Punktu informacyjnego Wichrogrodu. To pierwszy budynek po lewej, gdy przejdziesz przez główną bramę od strony Doliny Bohaterów.', 0),
(2901, 'koKR', 'Jakiego nauczyciela klasy szukasz?', 'Jakiego nauczyciela klasy szukasz?', 0),
(2903, 'koKR', 'Magowie zbierają się w Sanktuarium Czarodziejów w Dzielnicy Magów. Niezłą mają tam wieżę. Przy niej nasze koszary wyglądają jak chłopskie chałupy.', 'Magowie zbierają się w Sanktuarium Czarodziejów w Dzielnicy Magów. Niezłą mają tam wieżę. Przy niej nasze koszary wyglądają jak chłopskie chałupy.', 0),
(2904, 'koKR', 'Och, szukasz tajemnego oświecenia? Nie ma lepszego miejsca niż Sanktuarium Czarodziejów w Dzielnicy Magów.', 'Och, szukasz tajemnego oświecenia? Nie ma lepszego miejsca niż Sanktuarium Czarodziejów w Dzielnicy Magów.', 0),
(2905, 'koKR', 'Wygląda na to, że chcesz porozmawiać z Maginorem Dumasem! Zwykle znajdziesz go w Sanktuarium Czarodziejów w Dzielnicy Magów. Choć nigdy nie wiadomo, kiedy i dokąd ci magowie się teleportują.', 'Wygląda na to, że chcesz porozmawiać z Maginorem Dumasem! Zwykle znajdziesz go w Sanktuarium Czarodziejów w Dzielnicy Magów. Choć nigdy nie wiadomo, kiedy i dokąd ci magowie się teleportują.', 0),
(2907, 'koKR', 'W takim razie chcesz porozmawiać z Osborne\'em. W Wichrogrodzie nie ma lepszego nauczyciela sztuki skradania się. Szukaj go na Starym Mieście.', 'W takim razie chcesz porozmawiać z Osborne\'em. W Wichrogrodzie nie ma lepszego nauczyciela sztuki skradania się. Szukaj go na Starym Mieście.', 0),
(2908, 'koKR', 'Bah, łotrzy tylko utrudniają nam robotę tu, w Wichrogrodzie. Chętnie wyciągnąłbym i Osborne\'a, i Mathiasa ze Starego Miasta prosto do Kazamat.', 'Bah, łotrzy tylko utrudniają nam robotę tu, w Wichrogrodzie. Chętnie wyciągnąłbym i Osborne\'a, i Mathiasa ze Starego Miasta prosto do Kazamat.', 0),
(2909, 'koKR', 'Jeśli szukasz łotrów, idź na Stare Miasto. To we wschodnim zakątku Wichrogrodu.', 'Jeśli szukasz łotrów, idź na Stare Miasto. To we wschodnim zakątku Wichrogrodu.', 0),
(2911, 'koKR', 'Wojowników zwykle znajdziesz w tawernie „Świnia i Gwizdek” albo w koszarach na Starym Mieście. Ale powiem ci, że w tawernie łatwiej kogoś znaleźć.', 'Wojowników zwykle znajdziesz w tawernie „Świnia i Gwizdek” albo w koszarach na Starym Mieście. Ale powiem ci, że w tawernie łatwiej kogoś znaleźć.', 0),
(2912, 'koKR', 'Szukasz szkolenia, co? Wyszkoliłbym cię lepiej niż ktokolwiek w Wichrogrodzie, ale straż mi tego zabrania. Chyba będziesz $gmusiał:musiała; zadowolić się którymś z tych wypaleńców kręcących się przy koszarach albo w tawernie „Świnia i Gwizdek” na Starym Mieście.', 'Szukasz szkolenia, co? Wyszkoliłbym cię lepiej niż ktokolwiek w Wichrogrodzie, ale straż mi tego zabrania. Chyba będziesz $gmusiał:musiała; zadowolić się którymś z tych wypaleńców kręcących się przy koszarach albo w tawernie „Świnia i Gwizdek” na Starym Mieście.', 0),
(2913, 'koKR', 'Rozejrzyj się na Starym Mieście, w koszarach albo w tawernie „Świnia i Gwizdek”. Jak pójdziesz do tawerny, koniecznie skosztuj tamtejszych trunków. Krasnoludzkie piwa mogą się przy nich schować, mówię ci.', 'Rozejrzyj się na Starym Mieście, w koszarach albo w tawernie „Świnia i Gwizdek”. Jak pójdziesz do tawerny, koniecznie skosztuj tamtejszych trunków. Krasnoludzkie piwa mogą się przy nich schować, mówię ci.', 0),
(2915, 'koKR', 'Cóż, Theridana albo Maldryna znajdziesz przy księżycowej studni w Parku. Idź w zachodnią część Wichrogrodu, na północ od Dzielnicy Magów, ale na zachód od Placu Katedralnego.', 'Cóż, Theridana albo Maldryna znajdziesz przy księżycowej studni w Parku. Idź w zachodnią część Wichrogrodu, na północ od Dzielnicy Magów, ale na zachód od Placu Katedralnego.', 0),
(2916, 'koKR', 'Jeśli szukasz nauczycieli druidów, idź do Parku. Theridana i Maldryna zwykle znajdziesz przy księżycowej studni w środku dzielnicy.', 'Jeśli szukasz nauczycieli druidów, idź do Parku. Theridana i Maldryna zwykle znajdziesz przy księżycowej studni w środku dzielnicy.', 0),
(2917, 'koKR', 'Dziecię natury, tak? W takim razie nie szukaj dalej niż księżycowa studnia w Parku.', 'Dziecię natury, tak? W takim razie nie szukaj dalej niż księżycowa studnia w Parku.', 0),
(2919, 'koKR', 'Katedra Światła na Placu Katedralnym to dom kapłanów Wichrogrodu. Znajdziesz tam arcykapłankę Laurenę.', 'Katedra Światła na Placu Katedralnym to dom kapłanów Wichrogrodu. Znajdziesz tam arcykapłankę Laurenę.', 0),
(2920, 'koKR', 'Laurena jest arcykapłanką Wichrogrodu. Znajdziesz ją w Katedrze Światła na Placu Katedralnym.', 'Laurena jest arcykapłanką Wichrogrodu. Znajdziesz ją w Katedrze Światła na Placu Katedralnym.', 0),
(2921, 'koKR', 'Radziłbym poszukać w Katedrze Światła na Placu Katedralnym.', 'Radziłbym poszukać w Katedrze Światła na Placu Katedralnym.', 0),
(2923, 'koKR', 'Jeśli chcesz zostać potężnym paladynem, nie ma lepszego nauczyciela niż lord Grayson Cieniołamacz. Znajdziesz go w Katedrze Światła na Placu Katedralnym.', 'Jeśli chcesz zostać potężnym paladynem, nie ma lepszego nauczyciela niż lord Grayson Cieniołamacz. Znajdziesz go w Katedrze Światła na Placu Katedralnym.', 0),
(2925, 'koKR', 'Thorfin Kamiennatarcza przybył do nas aż z Żelaznej Kuźni, by dzielić się z nami swoją wiedzą łowiecką. Jeśli nie przeszkadza ci zadymione powietrze Dzielnicy Krasnoludów, znajdziesz go w jego domu w północno-wschodniej części dzielnicy.', 'Thorfin Kamiennatarcza przybył do nas aż z Żelaznej Kuźni, by dzielić się z nami swoją wiedzą łowiecką. Jeśli nie przeszkadza ci zadymione powietrze Dzielnicy Krasnoludów, znajdziesz go w jego domu w północno-wschodniej części dzielnicy.', 0),
(2927, 'koKR', 'Co? Nie znam żadnych nauczycieli czarnoksiężników w Wichrogrodzie. \nChociaż... Widziano jakieś oznaki demonicznej aktywności w okolicy „Zarżniętego Jagnięcia” w Dzielnicy Magów. Może tam sprawdzisz.', 'Co? Nie znam żadnych nauczycieli czarnoksiężników w Wichrogrodzie. \nChociaż... Widziano jakieś oznaki demonicznej aktywności w okolicy „Zarżniętego Jagnięcia” w Dzielnicy Magów. Może tam sprawdzisz.', 0),
(2953, 'koKR', 'Jeśli potrzebujesz szkolenia z alchemii, w Wichrogrodzie jest tylko jedno miejsce, do którego musisz się udać... Alchemiczne Potrzeby. Znajdziesz je w Dzielnicy Magów, w zewnętrznym kręgu sklepów.', 'Jeśli potrzebujesz szkolenia z alchemii, w Wichrogrodzie jest tylko jedno miejsce, do którego musisz się udać... Alchemiczne Potrzeby. Znajdziesz je w Dzielnicy Magów, w zewnętrznym kręgu sklepów.', 0),
(2954, 'koKR', 'Musisz porozmawiać z krasnoludem Therumem Głębokuciem. Moim zdaniem jeden z najlepszych kowali w okolicy. Znajdziesz go w samym sercu Dzielnicy Krasnoludów.', 'Musisz porozmawiać z krasnoludem Therumem Głębokuciem. Moim zdaniem jeden z najlepszych kowali w okolicy. Znajdziesz go w samym sercu Dzielnicy Krasnoludów.', 0),
(2955, 'koKR', 'Jeśli chcesz zostać świetnym kucharzem, wybierz się do tawerny „Świnia i Gwizdek” na Starym Mieście i porozmawiaj ze Stephenem Rybackiem. Ten człowiek umie przyrządzić żeberka jak nikt inny.\nOch... przez ciebie zgłodniałem na jego słynne żeberka. Tylko nie licz, że nauczy cię tego przepisu!', 'Jeśli chcesz zostać świetnym kucharzem, wybierz się do tawerny „Świnia i Gwizdek” na Starym Mieście i porozmawiaj ze Stephenem Rybackiem. Ten człowiek umie przyrządzić żeberka jak nikt inny.\nOch... przez ciebie zgłodniałem na jego słynne żeberka. Tylko nie licz, że nauczy cię tego przepisu!', 0),
(2956, 'koKR', 'Nauczycielem inżynierii w Wichrogrodzie jest pomysłowy gnom o imieniu Lilliam Iskrowrzeciono. Znajdziesz go w głębi Dzielnicy Krasnoludów.', 'Nauczycielem inżynierii w Wichrogrodzie jest pomysłowy gnom o imieniu Lilliam Iskrowrzeciono. Znajdziesz go w głębi Dzielnicy Krasnoludów.', 0),
(2957, 'koKR', 'Katedra Światła to ośrodek całej sztuki leczenia w Wichrogrodzie. Znajdziesz tam Angelę Leifeld, która pomoże ci poznać ten fach.', 'Katedra Światła to ośrodek całej sztuki leczenia w Wichrogrodzie. Znajdziesz tam Angelę Leifeld, która pomoże ci poznać ten fach.', 0),
(2958, 'koKR', 'Tannysę znajdziesz przed Alchemicznymi Potrzebami w Dzielnicy Magów.', 'Tannysę znajdziesz przed Alchemicznymi Potrzebami w Dzielnicy Magów.', 0),
(2959, 'koKR', 'Chcesz się nauczyć garbarstwa, co? Nauczy cię Simon Tanner. Znajdziesz go na Starym Mieście, w „Ochronnej Skórze”.', 'Chcesz się nauczyć garbarstwa, co? Nauczy cię Simon Tanner. Znajdziesz go na Starym Mieście, w „Ochronnej Skórze”.', 0),
(2961, 'koKR', 'Najlepiej porozmawiaj z Gelmanem Kamiennorękim. Chyba ma dom w Dzielnicy Krasnoludów, ale nie pamiętam dokładnie. Sprawdziłbym tam.', 'Najlepiej porozmawiaj z Gelmanem Kamiennorękim. Chyba ma dom w Dzielnicy Krasnoludów, ale nie pamiętam dokładnie. Sprawdziłbym tam.', 0),
(2962, 'koKR', 'Jeśli chcesz się nauczyć skórowania, idź na Stare Miasto i zajrzyj do „Ochronnej Skóry”.', 'Jeśli chcesz się nauczyć skórowania, idź na Stare Miasto i zajrzyj do „Ochronnej Skóry”.', 0),
(2963, 'koKR', 'W „Tkaninach Duncana” pracuje jeden z najlepszych krawców w Wichrogrodzie, Georgio Bolero. Szukaj tego sklepu w Dzielnicy Magów.', 'W „Tkaninach Duncana” pracuje jeden z najlepszych krawców w Wichrogrodzie, Georgio Bolero. Szukaj tego sklepu w Dzielnicy Magów.', 0),
(2974, 'koKR', 'Dokąd mam ci wskazać drogę?', 'Dokąd mam ci wskazać drogę?', 0),
(3009, 'koKR', 'Nie ma to jak dzień spędzony na łowieniu ryb nad Kryształowym Jeziorem. Nauczył mnie tego Arnold Leland. Zwykle znajdziesz go na pomoście w Dzielnicy Kanałów, jak łowi ryby całymi dniami. \nAch, i nie wierz w żadne jego opowieści o potworach w kanałach.', 'Nie ma to jak dzień spędzony na łowieniu ryb nad Kryształowym Jeziorem. Nauczył mnie tego Arnold Leland. Zwykle znajdziesz go na pomoście w Dzielnicy Kanałów, jak łowi ryby całymi dniami. \nAch, i nie wierz w żadne jego opowieści o potworach w kanałach.', 0),
(3010, 'koKR', 'Lucan Cordell ma mały sklep nad kanałem przy Kazamatach. Na pewno nauczy cię sztuki zaklinania.', 'Lucan Cordell ma mały sklep nad kanałem przy Kazamatach. Na pewno nauczy cię sztuki zaklinania.', 0),
