(5298, 'koKR', 'Niech Światłość ma cię dziś w opiece.', 'Niech Światłość ma cię dziś w opiece.', 0),
(5299, 'koKR', 'Chcę dalej zgłębiać ścieżki Światłości.', 'Chcę dalej zgłębiać ścieżki Światłości.', 0),
